PRAGMA foreign_keys=OFF;
BEGIN TRANSACTION;
CREATE TABLE knowledge_entries (
                id TEXT PRIMARY KEY,
                entry_type TEXT NOT NULL,  -- 'wisdom', 'decision', 'pattern', 'insight', 'session'
                title TEXT NOT NULL,
                content TEXT NOT NULL,
                summary TEXT,
                component TEXT,
                tags TEXT,  -- JSON array of tags
                metadata TEXT,  -- JSON metadata
                confidence REAL DEFAULT 0.8,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                deleted_at TIMESTAMP,  -- Soft delete: NULL = active, timestamp = deleted
                access_count INTEGER DEFAULT 0,
                last_accessed TIMESTAMP
            );
CREATE TABLE knowledge_embeddings (
                knowledge_id TEXT PRIMARY KEY,
                embedding BLOB NOT NULL,
                embedding_model TEXT NOT NULL DEFAULT 'paraphrase-multilingual-MiniLM-L12-v2',
                FOREIGN KEY (knowledge_id) REFERENCES knowledge_entries (id) ON DELETE CASCADE
            );
CREATE TABLE session_contexts (
                id TEXT PRIMARY KEY,
                session_id TEXT NOT NULL,
                context_type TEXT NOT NULL,  -- 'analysis', 'decision', 'finding', 'todo', 'code_change'
                content TEXT NOT NULL,
                metadata TEXT,  -- JSON metadata
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
            );
CREATE TABLE knowledge_relationships (
                id TEXT PRIMARY KEY,
                parent_id TEXT NOT NULL,
                child_id TEXT NOT NULL,
                relationship_type TEXT NOT NULL,  -- 'depends_on', 'related_to', 'supersedes'
                strength REAL DEFAULT 0.5,
                created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                FOREIGN KEY (parent_id) REFERENCES knowledge_entries (id) ON DELETE CASCADE,
                FOREIGN KEY (child_id) REFERENCES knowledge_entries (id) ON DELETE CASCADE
            );
COMMIT;
