INSERT INTO knowledge_entries VALUES('0687986d','general','Phase 61: Generic Class/Struct/Module Definitions','Implemented generic type parameter definitions (class Box(T), struct Point(T), module Enumerable(T)) for Crystal parser. Parser: parse_type_parameters method parses (T,K,V) after name. Integration: parse_class, parse_struct, parse_module. AST fields from Phase 60. Commit 7a189b665, 740 tests pass.','Implemented generic type parameter definitions (class Box(T), struct Point(T), module Enumerable(T)) for Crystal parser. Parser: parse_type_parameters method parses (T,K,V) after name. Integration: parse_class, parse_struct, parse_module. AST fields from Phase 60. Commit 7a189b665, 740 tests pass.',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T10:36:38.601868','2025-10-26T10:36:38.601871',NULL,3,'2025-10-27T00:51:00.862491');
INSERT INTO knowledge_entries VALUES('8cbf6c64','general','Phase 62: Octal Escape Sequences Implementation','{"pattern": "Crystal lexer: Octal escape sequences (\\NNN format)", "solution": "parse_octal_fixed helper (1-3 digits, greedy) + integrated into lex_string and lex_char with proper offset handling", "evidence": "761 tests pass (+21 new tests), commit 366c07a62, CASSANDRA 95% confidence", "applicability": "Use for any lexer escape sequence implementation needing variable-length numeric parsing with greedy behavior", "anti_patterns": ["Hardcoding specific cases like \\0 instead of general \\NNN handler", "Not accounting for helper method already advancing lexer offset (causes double-advance bugs)", "Using fixed count instead of greedy parsing up to max (breaks \\78 = byte 7 + ''8'' pattern)"], "confidence": 0.95, "tags": ["crystal-gpt5", "lexer", "escape-sequences", "octal", "phase-62", "production-ready", "greedy-parsing"], "related_entries": ["Phase 59: hex escapes \\xXX", "Phase 58: unicode escapes \\uXXXX and \\u{...}", "Phase 53: octal_digit? helper"], "details": {"helper_method": {"name": "parse_octal_fixed", "location": "lexer.cr:1142-1155", "signature": "private def parse_octal_fixed(max_count : Int32) : Int32?", "behavior": "Parses 1-3 octal digits greedily, returns byte value or nil, advances lexer offset automatically", "implementation": "while count < max_count && octal_digit?(current_byte): value = value * 8 + digit_value"}, "integration_points": {"lex_string": "lexer.cr:546-556 - checks octal_digit?, calls parse_octal_fixed(3), uses next to skip extra advance", "lex_char": "lexer.cr:748-772 - similar but with early return pattern (like unicode/hex) to avoid common advance path"}, "design_decisions": {"unified_null_handling": "Removed hardcoded \\0 case (was at 507-508, 681-682), now handled as \\000 (special case of general octal)", "greedy_parsing": "Parse up to 3 digits, stop at non-octal digit (e.g., \\78 → byte 7 + ''8'', not error)", "consistent_pattern": "Follows Phase 59 hex escape implementation pattern for maintainability"}, "test_coverage": {"file": "spec/lexer_octal_escape_spec.cr", "count": 21, "categories": ["string literals (12): single/double/triple digit, \\0, \\000, special chars, mixed", "character literals (5): various digit counts and special values", "integration (4): arrays, method calls, multiple statements, mixed hex+octal"]}}}','{"pattern": "Crystal lexer: Octal escape sequences (\\NNN format)", "solution": "parse_octal_fixed helper (1-3 digits, greedy) + integrated into lex_string and lex_char with proper offset handling", "evidence": "761 tests pass (+21 new tests), commit 366c07a62, CASSANDRA 95% confidence", "applicability": "Use for any lexer escape sequence implementation needing variable-length numeric parsing with...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T10:48:41.738703','2025-10-26T10:48:41.738705',NULL,2,'2025-10-26T20:16:30.993169');
