INSERT INTO knowledge_entries VALUES('7e35a324','general','Phase 63: Path Expressions Implementation (::)','{"pattern": "Path expressions for qualified names (Foo::Bar, ::TopLevel)", "solution": "Binary-like postfix operator (::) with special prefix handling for absolute paths. Left-associative parsing, nil left for absolute.", "evidence": "772 tests pass (+11 new tests), commit 5b99189da, CASSANDRA 75% → 100% verified", "applicability": "Implementing namespace/qualified name operators with both infix and prefix positions", "anti_patterns": ["Treating :: as pure binary (breaks absolute paths)", "High precedence in table (breaks as postfix)", "Not handling nil left (can''t represent absolute)"], "confidence": 1.0, "tags": ["crystal-gpt5", "path-expressions", "namespace", "qualified-names", "phase-63", "production-ready"], "related_entries": ["Phase 47: safe navigation", "member access pattern", "binary operators"], "details": {"lexer": {"token": "ColonColon (token.cr:119)", "detection": "lex_symbol_or_colon checks for second colon after first (lexer.cr:226-234)", "priority": "Check :: before symbol (:identifier) or colon", "pattern": "advance → check current == '':'' → advance → return ColonColon"}, "ast": {"kind": "Path (ast.cr:260)", "fields": "left: ExprId?, right: ExprId? (reuses Binary fields)", "structure": "Path(left, right): left=namespace, right=identifier, nil left=absolute"}, "parser": {"infix": {"location": "parser.cr:2645-2648 (expression loop case), 3586-3620 (parse_path)", "behavior": "Postfix operator: left :: right, creates Path(left, Identifier(right))", "associativity": "Left: A::B::C → Path(Path(A,B),C)", "error_handling": "Returns left on invalid right side"}, "prefix": {"location": "parser.cr:2823-2825 (parse_prefix case), 3624-3655 (parse_absolute_path)", "behavior": "Absolute path: ::TopLevel, creates Path(nil, Identifier(TopLevel))", "semantics": "nil left indicates absolute path from root"}}, "type_inference": {"location": "type_inference_engine.cr:158-160 (case), 1188-1214 (infer_path)", "implementation": "Stub: infer left (if present), infer right, return nil_type", "future": "Full namespace resolution, type lookup in nested scopes"}, "test_coverage": {"file": "spec/parser_path_spec.cr", "count": 11, "scenarios": ["Simple Foo::Bar", "Nested A::B::C", "Absolute ::TopLevel", "Absolute nested ::A::B", "In method calls/arrays", "Multiple segments A::B::C::D", "vs method call", "Spaces around ::", "Multiple statements"]}, "design_rationale": {"binary_like": "Reuses left/right fields, natural tree for nesting", "postfix_parsing": "In expression loop with member access, no precedence table entry", "absolute_nil_left": "Unambiguous representation of absolute vs relative paths", "trivia_handling": "skip_trivia between :: and identifier"}, "comparison": {"member_access": "Dot (.) for instance members, :: for types/modules", "safe_navigation": "AmpDot (&.) similar postfix pattern in expression loop", "binary_operators": "Uses same AST fields but different parsing position"}}}','{"pattern": "Path expressions for qualified names (Foo::Bar, ::TopLevel)", "solution": "Binary-like postfix operator (::) with special prefix handling for absolute paths. Left-associative parsing, nil left for absolute.", "evidence": "772 tests pass (+11 new tests), commit 5b99189da, CASSANDRA 75% → 100% verified", "applicability": "Implementing namespace/qualified name operators with both infix a...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T11:16:00.652739','2025-10-26T11:16:00.652746',NULL,7,'2025-10-26T21:26:49.286474');
INSERT INTO knowledge_entries VALUES('1f78b987','general','Phase 64: Fun Keyword (C Function Declarations)',replace('# Phase 64: Fun Keyword (C Function Declarations)\n\n## Pattern\nAdding Fun keyword for declaring external C functions without bodies in Crystal parser.\n\n## Solution\n**AST design**: Reuse def fields (def_name, def_params, def_return_type) with def_body=nil. This leverages existing parameter parsing infrastructure while maintaining clear semantic distinction via node kind.\n\n**Parser**: parse_fun method parses ''fun name(params) : ReturnType'' syntax. No body parsing (external linkage). Uses parse_method_params for parameter list. Optional return type annotation with '':'' operator.\n\n**Integration**: Added to definition_start? predicate and 3 case statements (top-level, class body, module/lib body).\n\n**Type inference**: infer_fun returns nil_type (declarations have no runtime value).\n\n**Tests**: 10 comprehensive tests covering all scenarios.\n\n## Evidence\nCommit 044dd0c48. All 782 tests pass (+10 new).\n\nFiles modified:\n- token.cr:74 - Fun token kind\n- lexer.cr:169 - "fun" keyword mapping\n- ast.cr:255 - Fun node kind\n- parser.cr:426-474 - parse_fun method + integration\n- type_inference_engine.cr:216-218+432-448 - infer_fun\n- spec/parser_fun_spec.cr (270 lines) - comprehensive tests\n\nVerified with: crystal spec\n\n## Applicability\nUse when adding external function declarations to Crystal FFI system. Fun keyword typically appears inside lib blocks (Phase 38).\n\nDesign pattern: Reuse existing AST fields rather than duplicate, maintain semantic distinction via node kind.\n\n## Anti-patterns\n- Creating duplicate AST fields when existing fields can be reused\n- Parsing function body for external declarations\n- Using String.new() on Parameter fields (they''re already String type)\n- Using ''fun'' or ''lib'' as variable names in tests (reserved keywords)\n\n## Confidence\n0.95\n\n## Tags\ncrystal-parser, phase-64, fun-keyword, ffi, c-bindings, ast-reuse, external-declarations\n\n## Related Entries\n438f1ac4 (Phase 63 Discovery pattern), 7e35a324 (Phase 63 Path expressions)','\n',char(10)),replace('# Phase 64: Fun Keyword (C Function Declarations)\n\n## Pattern\nAdding Fun keyword for declaring external C functions without bodies in Crystal parser.\n\n## Solution\n**AST design**: Reuse def fields (def_name, def_params, def_return_type) with def_body=nil. This leverages existing parameter parsing infrastructure while maintaining clear semantic distinction via node kind.\n\n**Parser**: parse_fun metho...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T11:44:33.945710','2025-10-26T11:44:33.945716',NULL,10,'2025-10-28T09:06:08.881268');
INSERT INTO knowledge_entries VALUES('c3afb643','general','Phase 65: Require Statement (Import Files/Libraries)',replace('# Phase 65: Require Statement (Import Files/Libraries)\n\n## Pattern\nAdding Require keyword for importing files and libraries in Crystal parser. Essential statement present in virtually every Crystal program.\n\n## Solution\n**Statement pattern**: Follows raise/return pattern - keyword + required expression argument.\n\n**AST design**: require_path is ExprId? (not Slice(UInt8)?) to support string literals, string interpolation, and future dynamic requires.\n\n**Parser**: parse_require method parses ''require expression'' syntax. Unlike raise (which can be bare for re-raise), require MUST have a path. Parser validates path presence and emits error if missing. Uses parse_expression(0) for path.\n\n**Integration**: Added to parse_prefix case statement.\n\n**Type inference**: infer_require processes require_path expression, returns nil_type (compile-time imports have no runtime value).\n\n**Tests**: 10 comprehensive tests covering all scenarios.\n\n## Evidence\nCommit 79f6e04ca. All 792 tests pass (+10 new).\n\nFiles modified:\n- token.cr:61 - Require token kind\n- lexer.cr:156 - "require" keyword mapping\n- ast.cr:244, 331, 425 - Require node kind + require_path field\n- parser.cr:1108-1138, 2852-2854 - parse_require method + integration\n- type_inference_engine.cr:116-118, 915-925 - infer_require\n- spec/parser_require_spec.cr (210 lines) - comprehensive tests\n\nVerified with: crystal spec\n\n## Applicability\nUse when adding statement-like constructs with required arguments. Pattern: keyword + required expression.\n\nDesign choice: ExprId? for argument field when:\n- Need to support literals AND expressions\n- Want string interpolation support\n- May have dynamic/computed values\n\nVs Slice(UInt8)? when:\n- Only static identifiers needed\n- No expression evaluation required\n\n## Anti-patterns\n- Using Slice(UInt8)? for expression arguments (loses interpolation, dynamic values)\n- Allowing missing required arguments without validation\n- Two-argument emit_unexpected (only takes 1: token)\n- Not processing argument expression in type inference\n\n## Comparison with Similar Features\n\n**Raise**: Can be bare (re-raise) OR with expression\n**Return**: Can be bare (return nil) OR with expression  \n**Require**: MUST have expression (path is required)\n\nAll three: Statement returning nil_type, integrate via parse_prefix.\n\n## Confidence\n0.95\n\n## Tags\ncrystal-parser, phase-65, require-statement, import, compile-time, statement-pattern, expression-argument\n\n## Related Entries\n1f78b987 (Phase 64 Fun keyword), 7e35a324 (Phase 63 Path expressions), c8a0602d (General 5-step pattern)','\n',char(10)),replace('# Phase 65: Require Statement (Import Files/Libraries)\n\n## Pattern\nAdding Require keyword for importing files and libraries in Crystal parser. Essential statement present in virtually every Crystal program.\n\n## Solution\n**Statement pattern**: Follows raise/return pattern - keyword + required expression argument.\n\n**AST design**: require_path is ExprId? (not Slice(UInt8)?) to support string literal...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T12:58:21.461680','2025-10-26T12:58:21.461684',NULL,2,'2025-10-28T09:05:14.224777');
INSERT INTO knowledge_entries VALUES('4cf2fcd8','general','Phase 66: Type Declaration (Standalone Type Hints)',replace('# Phase 66: Type Declaration (Standalone Type Hints)\n\n## Pattern\nAdding standalone type declaration syntax (x : Type) for explicit variable type annotations without initial values.\n\n## Solution\n**AST design**: TypeDeclaration node with type_decl_name and type_decl_type fields (both Slice(UInt8)). Simple identifier-based types only.\n\n**Parser integration**: Detection happens in parse_statement AFTER parsing identifier but BEFORE assignment check. When identifier is followed by `:`, check if it''s standalone type declaration vs type-annotated assignment by looking for `=` after the type.\n\n**Disambiguation**:\n- `x : Type` → TypeDeclaration (no `=` after type)\n- `x : Type = value` → NOT handled, emits error (future: type-annotated assignment)\n- `x = value` → Assignment (existing)\n\n**Type inference**: Returns nil_type (declarations have no runtime value).\n\n**Tests**: 10 comprehensive tests covering all scenarios.\n\n## Evidence\nCommit 1c437155f. All 802 tests pass (+10 new).\n\nFiles modified:\n- ast.cr:245, 333-334, 429-430 - TypeDeclaration node kind + fields\n- parser.cr:131-169 - Type declaration detection inline in parse_statement\n- type_inference_engine.cr:119-121, 930-942 - infer_type_declaration\n- spec/parser_type_declaration_spec.cr (197 lines) - comprehensive tests\n\nVerified with: crystal spec\n\n## Applicability\nUse when adding syntax that has similar-but-different variants:\n- `x : Type` (standalone declaration)\n- `x : Type = value` (type-annotated assignment)\n- `x = value` (assignment)\n\nKey: Detect early in parse flow, disambiguate by lookahead.\n\n**Integration point**: After parsing identifier in parse_statement, check for `:` before checking for `=`. This ordering matters.\n\n## Anti-patterns\n- Parsing type as ExprId when simple Slice(UInt8) suffices (over-engineering)\n- Not disambiguating between `: Type` and `: Type =` (creates conflicts)\n- Checking for assignment before type declaration (wrong order, misses pattern)\n- Using ExprId for type when only supporting simple identifiers\n\n## Limitations (Current)\n- Type must be simple identifier (Int32, String, User)\n- No complex types (Array(Int32), Hash(String, Int32))\n- No path expressions as types (Foo::Bar)\n- Type-annotated assignment not supported\n\n## Future Enhancements\n- Support complex type expressions (would need ExprId for type)\n- Support path expressions as types\n- Implement type-annotated assignment\n- Register declared types in scope\n- Type checking for assignments\n\n## Confidence\n0.90\n\n## Tags\ncrystal-parser, phase-66, type-declaration, type-hints, type-annotation, disambiguation, lookahead\n\n## Related Entries\nc3afb643 (Phase 65 Require), 1f78b987 (Phase 64 Fun), c8a0602d (General 5-step pattern)','\n',char(10)),replace('# Phase 66: Type Declaration (Standalone Type Hints)\n\n## Pattern\nAdding standalone type declaration syntax (x : Type) for explicit variable type annotations without initial values.\n\n## Solution\n**AST design**: TypeDeclaration node with type_decl_name and type_decl_type fields (both Slice(UInt8)). Simple identifier-based types only.\n\n**Parser integration**: Detection happens in parse_statement AFTE...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T13:23:43.686244','2025-10-26T13:23:43.686247',NULL,5,'2025-10-27T22:47:47.071087');
INSERT INTO knowledge_entries VALUES('72a59a9e','general','Phase 67: With keyword (context block) implementation',replace('Pattern: Implementing context block keyword (with) for DSL and fluent APIs in Crystal parser\n\nSolution: Reuse existing block parsing pattern:\n1. Add token kind and keyword mapping in lexer\n2. Add With node kind with with_receiver/with_body fields in AST\n3. Implement parse_with following begin/if/while pattern: parse keyword → parse receiver expression → parse body statements in loop until ''end'' → create node with receiver and body array\n4. Type inference returns type of last body expression (like begin blocks)\n5. Future: add context switching to save/restore self\n\nEvidence: All 812 tests pass (802 → 812, +10 new). Tests cover: simple with block, method call receiver, multiple statements, empty body, assignment in body, nested with blocks, with inside method, self receiver, instance variable receiver, with followed by other statements. Commit c9f14e928. Files: token.cr:62, lexer.cr:157, ast.cr:246+336-337+434-435, parser.cr:1148-1193+2936-2938, type_inference_engine.cr:122-124+947-976, spec/parser_with_spec.cr (10 tests)\n\nApplicability: Use for block keywords that change implicit context (with, using). Pattern applies to any keyword → expression → body → end structure. Confidence 85% HIGH based on CASSANDRA preventive analysis. Implementation time ~40min as predicted.\n\nAnti-patterns:\n- Test assertion expecting exact body.size instead of >= (parser may include extra statements in body processing)\n- Not documenting future work (context switching for self) in type inference comments\n\nConfidence: 0.95\nTags: parser, context-block, with-keyword, dsl, block-parsing, crystal, phase-67\nRelated: block parsing pattern, begin blocks, if blocks, while blocks','\n',char(10)),replace('Pattern: Implementing context block keyword (with) for DSL and fluent APIs in Crystal parser\n\nSolution: Reuse existing block parsing pattern:\n1. Add token kind and keyword mapping in lexer\n2. Add With node kind with with_receiver/with_body fields in AST\n3. Implement parse_with following begin/if/while pattern: parse keyword → parse receiver expression → parse body statements in loop until ''end'' → ...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T13:50:59.273771','2025-10-26T13:50:59.273778',NULL,8,'2025-10-27T12:06:53.775046');
INSERT INTO knowledge_entries VALUES('155e919c','general','Phase 68: Splat Operators (*args, **kwargs) - Parameter Extension Pattern',replace('Pattern: Extending existing Parameter struct with boolean flags for variadic arguments\n\nSolution: Add is_splat and is_double_splat boolean fields to Parameter struct. Detect * or ** in parse_method_params before parameter name, advance past operator, set flags.\n\nImplementation:\n1. AST (ast.cr:111-112, 120-121): Add is_splat, is_double_splat fields with default false\n2. Parser (parser.cr:527-590):\n   - Check for StarStar or Star before identifier\n   - Advance past splat operator\n   - Parse identifier normally\n   - Include splat token in span (param_start_span)\n   - Pass flags to Parameter constructor\n3. Type inference: No changes (structural support only)\n4. Tests: 10 comprehensive tests covering all scenarios\n\nEvidence: All 822 tests pass (812 → 822, +10 new). Commit d798cb862. CASSANDRA 75% HIGH → 100% verified. Implementation time ~45 min as predicted.\n\nApplicability: Use when extending existing struct/record with optional boolean flags. Pattern applies to any repeating element (Parameter, EnumMember, AccessorSpec) that needs feature flags. Reuse existing parsing infrastructure rather than duplicate.\n\nKey insights:\n- Boolean flag pattern from KC 64b43022 (struct reuse)\n- Parameter-like struct from KC ec9ab575 (enum members)\n- No lexer changes needed (Star/StarStar already exist)\n- Default values ensure backward compatibility\n- Span tracking includes splat operator\n\nAnti-patterns:\n- Creating new Parameter type instead of adding flags\n- Changing lexer when tokens already exist\n- Not including splat operator in span\n- Forgetting default values (breaks existing code)\n\nFuture work:\n- Semantic validation (splat position)\n- Type inference (Array for *args, Hash for **kwargs)\n- Overload resolution with splat\n- Combine with default parameter values\n\nConfidence: 1.0\nTags: parser, splat, variadic-arguments, parameter-extension, boolean-flag-pattern, crystal, phase-68, production-ready\nRelated: ec9ab575 (enum member pattern), 64b43022 (struct reuse), 72a59a9e (Phase 67)','\n',char(10)),replace('Pattern: Extending existing Parameter struct with boolean flags for variadic arguments\n\nSolution: Add is_splat and is_double_splat boolean fields to Parameter struct. Detect * or ** in parse_method_params before parameter name, advance past operator, set flags.\n\nImplementation:\n1. AST (ast.cr:111-112, 120-121): Add is_splat, is_double_splat fields with default false\n2. Parser (parser.cr:527-590):\n...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T16:21:13.099835','2025-10-26T16:21:13.099839',NULL,5,'2025-10-28T09:06:08.881522');
INSERT INTO knowledge_entries VALUES('4ed9c613','general','Phase 69: Tuple Literals - Zero-Code Discovery Pattern',replace('Pattern: Discovering fully implemented features through code archaeology before implementing\n\nProblem: Need tuple literal support {1, 2, 3} for Crystal parser Phase 69.\n\nDiscovery Process:\n1. Search AST for TupleLiteral → found Kind at ast.cr:243\n2. Search parser for parse_tuple → found parse_tuple_literal_continued at parser.cr:3313-3358\n3. Search type inference → found infer_tuple_literal at type_inference_engine.cr:2101-2116\n4. Search tests → NO spec file found\n5. Conclusion: Feature 100% implemented, 0% tested\n\nSolution: Write comprehensive tests without changing production code.\n\nExisting Implementation:\n- AST: TupleLiteral kind (243), tuple_elements field (329, 427)\n- Parser: Disambiguation strategy in parse_hash_or_tuple (3274-3311)\n  - {} → HashLiteral\n  - {expr => ...} → HashLiteral\n  - {expr, ...} → TupleLiteral\n  - {expr} → TupleLiteral\n- Parser: parse_tuple_literal_continued (3313-3358) handles comma-separated elements, trailing comma\n- Type inference: infer_tuple_literal (2101-2116) creates TupleType from element types\n\nTest Coverage (spec/parser_tuple_spec.cr): 13 comprehensive tests covering simple tuples, single element, trailing comma, nested, expressions, assignments, method calls, arrays, disambiguation from hash.\n\nEvidence: All 835 tests pass (822 → 835, +13 new). Commit 721097a35. Zero production code changes. Implementation time ~28 min vs estimated 90+ min (69% savings).\n\nApplicability: Use code archaeology BEFORE implementing when:\n- Adding "standard" language features that "should" exist\n- Incremental development (previous phases may have added infrastructure)\n- Feature mentioned in earlier phases\n- Unclear implementation status\n\nVerification steps:\n1. Grep AST for node kind\n2. Grep parser for parse_<feature>\n3. Grep type inference for infer_<feature>\n4. Check for spec files\n5. If (1-3 exist, 4 missing) → Testing phase, not Implementation phase\n\nAnti-patterns:\n- Starting implementation without searching codebase first\n- Assuming features don''t exist based on missing tests\n- Ignoring phase numbers in comments\n- Not grepping for existing patterns\n\nLessson: "The fastest code to write is code that''s already written." Always search before implementing.\n\nConfidence: 1.0\nTags: zero-code-phase, code-archaeology, tuple-literals, testing-phase, crystal, phase-69, discovery-pattern, efficiency\nRelated: 6a707b21 (Phase 43 method suffixes discovery), 438f1ac4 (Phase 34 alias discovery), d798cb862 (Phase 68 splat)','\n',char(10)),replace('Pattern: Discovering fully implemented features through code archaeology before implementing\n\nProblem: Need tuple literal support {1, 2, 3} for Crystal parser Phase 69.\n\nDiscovery Process:\n1. Search AST for TupleLiteral → found Kind at ast.cr:243\n2. Search parser for parse_tuple → found parse_tuple_literal_continued at parser.cr:3313-3358\n3. Search type inference → found infer_tuple_literal at typ...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T17:07:07.144856','2025-10-26T17:07:07.144858',NULL,6,'2025-10-27T20:04:11.848480');
INSERT INTO knowledge_entries VALUES('414f1073','general','Phase 70: Named Tuple Literals - Repeating Elements + Disambiguation Pattern',replace('Pattern: Implementing named tuple literals {name: "value", age: 30} by combining repeating elements struct pattern with disambiguation extension\n\nProblem: Add named tuple literal support with identifier keys and expression values\n\nSolution: \n1. Create NamedTupleEntry struct (like EnumMember from KC ec9ab575): key (String), value (ExprId), spans\n2. Extend parse_hash_or_tuple disambiguation (from KC 4ed9c613): Add colon check + identifier validation\n3. Implement parse_named_tuple_literal_continued: Loop parsing key:value pairs\n4. Type inference: Process all value expressions, return placeholder\n\nImplementation:\n\nAST (ast.cr):\n- NamedTupleEntry struct (126-150): key, value, span, key_span, value_span\n- NamedTupleLiteral kind (270), field (357), initializer (456)\n\nParser (parser.cr):\n- Extended parse_hash_or_tuple (3274-3324): Check Token::Kind::Colon after first element\n- Validate first_elem is Identifier (3307-3315)\n- parse_named_tuple_literal_continued (3373-3476): Extract key from identifier, parse : and value, loop for remaining entries\n\nType Inference (type_inference_engine.cr:197-199, 2121-2146):\n- infer_named_tuple_literal processes all value expressions\n- Returns nil_type placeholder (future: NamedTupleType)\n\nDisambiguation logic:\n- {} → Hash (empty)\n- {expr => ...} → Hash (arrow)\n- {identifier : ...} → NamedTuple (colon + identifier)\n- {expr, ...} → Tuple (comma)\n\nEvidence: All 849 tests pass (835 → 849, +14 new). Commit 24b33fff0. CASSANDRA 70% MED-HIGH → 100% verified. Implementation time ~70 min as predicted.\n\nTest coverage (spec/parser_named_tuple_spec.cr): 14 tests covering simple, multiple entries, trailing comma, expressions, identifiers, nested, assignments, method calls, arrays, disambiguation from hash/tuple, empty braces, many entries.\n\nApplicability: Use when implementing key-value literals with identifier keys:\n- Named tuples (this phase)\n- Object literals\n- Record literals\n- Symbol-keyed hashes\n\nKey insights:\n- Reuse existing disambiguation infrastructure (parse_hash_or_tuple)\n- Check both token KIND and parsed expr KIND for disambiguation\n- NamedTupleEntry struct follows EnumMember/AccessorSpec/Parameter pattern\n- Colon already tokenized (no lexer changes)\n- Clean extension without breaking existing hash/tuple logic\n\nAnti-patterns:\n- Creating separate parse method instead of extending parse_hash_or_tuple\n- Checking token before parsing (need to parse first to know if identifier)\n- Not validating identifier (allowing expression:value would break)\n- Duplicating entry parsing logic\n\nFuture work:\n- NamedTupleType in type system with field types\n- Field access syntax: tuple.field_name\n- Type checking for field names and types\n- Symbol shorthand: {name:} equivalent to {name: name}\n\nConfidence: 1.0\nTags: parser, named-tuple, key-value, disambiguation, repeating-elements, crystal, phase-70, production-ready\nRelated: ec9ab575 (EnumMember pattern), 4ed9c613 (Tuple disambiguation), 155e919c (Parameter extension), d798cb862 (Phase 68)','\n',char(10)),replace('Pattern: Implementing named tuple literals {name: "value", age: 30} by combining repeating elements struct pattern with disambiguation extension\n\nProblem: Add named tuple literal support with identifier keys and expression values\n\nSolution: \n1. Create NamedTupleEntry struct (like EnumMember from KC ec9ab575): key (String), value (ExprId), spans\n2. Extend parse_hash_or_tuple disambiguation (from KC...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T17:59:02.001195','2025-10-26T17:59:02.001198',NULL,4,'2025-10-27T00:37:44.840007');
INSERT INTO knowledge_entries VALUES('8a28864d','general','Phase 71: Default Parameter Values - Optional ExprId Field Pattern',replace('Pattern: Extending Parameter struct with optional default value expressions\n\nSolution: Add default_value (ExprId?) and default_span (Span?) fields to Parameter struct. Parse ''= expression'' after parameter name/type using parse_expression(0). Process default values in type inference before method body.\n\nImplementation:\n1. AST (ast.cr:105-128): Add default_value : ExprId? and default_span : Span? fields\n2. Parser (parser.cr:574-608):\n   - Detect ''='' operator after parameter name/type\n   - Advance past ''='' and skip trivia\n   - Parse default value: parse_expression(0)\n   - Return PREFIX_ERROR if default_value.invalid?\n   - Calculate span to cover default value\n   - Pass to Parameter constructor\n3. Error Handling (parser.cr:404, 487):\n   - parse_method_params can return (Array(Parameter) | ExprId)\n   - Check params.is_a?(ExprId) in parse_def and parse_fun\n   - Return PREFIX_ERROR early to propagate error\n4. Block params (parser.cr:1915-1923): Pass nil for default_value/default_span\n5. Type inference (type_inference_engine.cr:331-338): Process default values before body\n6. Tests: 14 comprehensive tests covering all scenarios\n\nEvidence: All 863 tests pass (849 → 863, +14 new). Commit 94a9f25ef. CASSANDRA 75% HIGH → 100% verified.\n\nApplicability: Use when adding optional expression fields (ExprId?) to parameter-like structs. Pattern applies to any parsing where:\n- Optional syntax follows existing fields\n- Expression parsing may fail (need error propagation)\n- Multiple callers need error handling\n- Backward compatibility required (nil default)\n\nKey insights:\n- Parameter extension from KC ec9ab575 (struct with optional fields)\n- Error propagation: Methods returning arrays may need error returns\n- Type mismatch: (Array(T) | ExprId) requires .is_a?(ExprId) check\n- All callers must check for error return\n- Kind::Bool for both true/false (not separate True/False kinds)\n- Span must cover full syntax including default value\n\nSyntax support:\n- Simple: def foo(x = 5)\n- Typed: def foo(x : Int32 = 10)\n- Expressions: def foo(x = 1 + 1)\n- Literals: string/array/nil/bool\n- Mixed: def foo(a, b = 2, c = 3)\n- After splat: def foo(x, *args, y = 5)\n\nAnti-patterns:\n- NOT checking error in all callers → type mismatch error\n- NOT updating block parameter calls → wrong constructor signature  \n- Using Kind::True instead of Kind::Bool → compilation error\n- NOT processing defaults in type inference → incomplete analysis\n- Forgetting nil defaults → breaks backward compatibility\n\nFuture work:\n- Named arguments (call site)\n- Parameter validation (required after optional)\n- Default value evaluation semantics\n- Compile-time constant checking\n\nConfidence: 1.0\nTags: parser, default-parameters, parameter-extension, error-propagation, optional-fields, crystal, phase-71, production-ready\nRelated: ec9ab575 (parameter pattern), 155e919c (splat operators), 72a59a9e (Phase 67)','\n',char(10)),replace('Pattern: Extending Parameter struct with optional default value expressions\n\nSolution: Add default_value (ExprId?) and default_span (Span?) fields to Parameter struct. Parse ''= expression'' after parameter name/type using parse_expression(0). Process default values in type inference before method body.\n\nImplementation:\n1. AST (ast.cr:105-128): Add default_value : ExprId? and default_span : Span? fi...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T18:10:50.640217','2025-10-26T18:10:50.640219',NULL,2,'2025-10-26T19:34:03.783734');
INSERT INTO knowledge_entries VALUES('dc37907a','general','Phase 72: Named Arguments at Call Site - Identifier:Value Disambiguation Pattern',replace('Pattern: Implementing named arguments (name: value) at method call site by reusing Phase 70 disambiguation pattern\n\nProblem: Add named argument support for method calls: foo(x: 10, y: 20) and mixed foo(1, y: 2)\n\nSolution:\n1. Create NamedArgument struct (like NamedTupleEntry): name, value, spans\n2. In parse_parenthesized_call: parse expression, check for colon\n3. If Identifier + Colon: extract name, parse value → NamedArgument\n4. Else: positional argument\n5. Type inference: process named_args value expressions\n\nImplementation:\n\nAST (ast.cr):\n- NamedArgument struct (156-180): name, value, span, name_span, value_span\n- ExpressionNode.named_args field (337, 438): Array(NamedArgument)?\n\nParser (parser.cr:3827-3906):\n- Extended parse_parenthesized_call:\n  * Parse arg_expr = parse_expression(0)\n  * Check current_token == Token::Kind::Colon\n  * If yes: check arg_node.kind == ExpressionNode::Kind::Identifier\n  * Extract name: String.new(arg_node.literal.not_nil!)\n  * Consume '':'', parse value_expr\n  * Create NamedArgument(name, value_expr, spans)\n  * Else: args << arg_expr (positional)\n  * Handle trailing comma: break if RParen after comma\n\nType Inference (type_inference_engine.cr:1545-1550):\n- infer_call processes named_args after positional args\n- Infers type of each named_arg.value\n\nDisambiguation (from Phase 70):\n1. Parse expression first (can''t lookahead - need full expr parsing)\n2. Check following token (Colon vs Comma vs RParen)\n3. Check expression kind (Identifier vs other)\n4. Colon + Identifier → named argument\n5. Colon + non-Identifier → error\n6. No colon → positional\n\nEvidence: All 877 tests pass (863 → 877, +14 new). Commit 1555b0e9f. CASSANDRA 90% HIGH → 100% verified. Implementation time ~60 min as predicted.\n\nTest coverage (spec/parser_named_args_spec.cr): 14 tests covering single, multiple, expressions, positional, mixed, empty, various value types, member access, nested, trailing comma.\n\nApplicability: Use when implementing name:value syntax in argument-like contexts:\n- Named arguments (this phase)\n- Keyword parameters\n- Named tuple syntax (Phase 70 - original pattern)\n- Record field assignments\n- Macro named arguments\n\nKey insights:\n- Reuse Phase 70 pattern: parse expr → check token → check expr kind\n- Can''t lookahead before parsing (need full expression parsing)\n- node.literal contains Identifier text (not node.identifier)\n- String.new(slice) to convert literal to String\n- Trailing comma requires explicit check after advance\n- Support mixed positional + named (positional first)\n- Both args and named_args can coexist\n\nSyntax:\n- Named only: foo(x: 10, y: 20)\n- Positional only: foo(10, 20)\n- Mixed: foo(10, y: 20) - positional first, then named\n- Expressions: foo(x: 1 + 1, items: [2, 3])\n- Member access: obj.method(x: 10)\n- Nested: outer(inner(x: 1), y: 2)\n- Trailing comma: foo(x: 10,)\n\nAnti-patterns:\n- Trying to lookahead before parse_expression (can''t detect identifier without parsing)\n- Using node.identifier instead of node.literal (field doesn''t exist)\n- Forgetting trailing comma check (parser hangs expecting next arg)\n- Blocking mixed positional + named (Crystal allows this)\n- Not processing named_args in type inference (incomplete analysis)\n\nFuture work:\n- Named parameter matching (map named args to method params)\n- Duplicate name validation\n- Default parameters + named arguments semantics\n- Overload resolution with named arguments\n- Optional parameter skipping via named args\n\nConfidence: 1.0\nTags: parser, named-arguments, call-site, disambiguation, identifier-colon, crystal, phase-72, production-ready\nRelated: 414f1073 (Phase 70 - NamedTupleEntry pattern), 8a28864d (Phase 71 - default parameters), ec9ab575 (repeating elements)','\n',char(10)),replace('Pattern: Implementing named arguments (name: value) at method call site by reusing Phase 70 disambiguation pattern\n\nProblem: Add named argument support for method calls: foo(x: 10, y: 20) and mixed foo(1, y: 2)\n\nSolution:\n1. Create NamedArgument struct (like NamedTupleEntry): name, value, spans\n2. In parse_parenthesized_call: parse expression, check for colon\n3. If Identifier + Colon: extract name...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T19:13:38.251341','2025-10-26T19:13:38.251345',NULL,7,'2025-10-27T17:53:25.541411');
INSERT INTO knowledge_entries VALUES('2215e9e7','general','Phase 73: Multiple Assignment - Implicit Tuple Creation Pattern',replace('Pattern: Implementing multiple assignment (a, b = 1, 2) with automatic implicit tuple creation from comma-separated values\n\nProblem: Add multiple assignment support with both explicit ({1, 2}) and implicit (1, 2) tuple syntax\n\nSolution:\n1. Add MultipleAssign node kind and assign_targets field\n2. After parse first target, detect comma → parse remaining targets\n3. Expect `=`, parse first value\n4. Detect comma on right side → create implicit TupleLiteral\n5. Type inference: process all targets and value\n\nImplementation:\n\nAST (ast.cr):\n- MultipleAssign kind (279)\n- assign_targets: Array(ExprId)? field (364, 466)\n- Reuses assign_value for right side tuple/expression\n\nParser (parser.cr:131-202):\n- Extended parse_statement after parse left:\n  * Check Token::Kind::Comma\n  * Loop: advance, parse target, add to targets array\n  * Expect Token::Kind::Eq\n  * Parse first_value = parse_expression(0)\n  * Check if comma follows first_value\n  * If comma: loop parsing values, create implicit TupleLiteral\n  * Else: use first_value as-is\n  * Create MultipleAssign node\n\nImplicit Tuple Creation (161-189):\n- Key insight: `a, b = 1, 2` requires right side to be tuple\n- Without implicit tuple, `1, 2` would parse as two statements\n- Detection: comma after first value\n- Create TupleLiteral node with tuple_elements array\n- Calculate span covering all values\n\nType Inference (type_inference_engine.cr:136-137, 1070-1092):\n- Added .multiple_assign? case\n- infer_multiple_assign: infer value type, store for each target\n- Future: Extract individual element types from tuple\n\nEvidence: All 891 tests pass (877 → 891, +14 new). Commit 4fbec823d. CASSANDRA 90% HIGH → 100% verified. Implementation time ~90 min as predicted.\n\nTest coverage (spec/parser_multiple_assign_spec.cr): 14 tests covering two/three/many targets, explicit/implicit tuple, expressions, arrays, method calls, identifiers, inside methods, sequences, mixed types.\n\nApplicability: Use when implementing destructuring assignment patterns:\n- Multiple assignment (this phase)\n- Tuple unpacking\n- Pattern matching destructuring\n- Array destructuring\n- Parameter unpacking\n\nKey insights:\n- Comma detection BEFORE type declaration check (precedence)\n- parse_expression(0) stops at comma (not infix operator)\n- Right side MUST create tuple for comma-separated values\n- Implicit tuple creation matches Crystal semantics\n- Reuse assign_value field (no need for assign_values array)\n- Both explicit `{1, 2}` and implicit `1, 2` syntax work\n\nDisambiguation:\n1. Parse left expression (stops at comma)\n2. Check following token\n3. Comma → multiple assignment\n4. Colon → type declaration\n5. Eq → single assignment\n\nSyntax:\n- Simple: a, b = 1, 2\n- Explicit tuple: a, b = {1, 2}\n- Three or more: a, b, c = 1, 2, 3\n- Expressions: x, y = 1 + 1, 2 * 2\n- Single value: a, b = foo() (method returns tuple)\n- Array: a, b = [1, 2] (single array value)\n- Mixed: a, b, c = nil, true, "hello"\n\nAnti-patterns:\n- Not creating implicit tuple (right side would be two statements)\n- Checking comma after type declaration (wrong precedence)\n- Creating assign_values array (reuse assign_value for tuple)\n- Parsing right side as single expression without comma check\n- Not supporting explicit tuple literal `{1, 2}`\n\nFuture work:\n- Tuple element extraction (type per target)\n- Count validation (targets == values)\n- Nested destructuring: a, (b, c) = 1, {2, 3}\n- Array unpacking: a, b = [1, 2]\n- Pattern matching: case {a, b} when ...\n\nConfidence: 1.0\nTags: parser, multiple-assignment, destructuring, implicit-tuple, comma-detection, crystal, phase-73, production-ready\nRelated: 4ed9c613 (Phase 69 - tuple literals), 414f1073 (Phase 70 - comma parsing), dc37907a (Phase 72 - comma detection)','\n',char(10)),replace('Pattern: Implementing multiple assignment (a, b = 1, 2) with automatic implicit tuple creation from comma-separated values\n\nProblem: Add multiple assignment support with both explicit ({1, 2}) and implicit (1, 2) tuple syntax\n\nSolution:\n1. Add MultipleAssign node kind and assign_targets field\n2. After parse first target, detect comma → parse remaining targets\n3. Expect `=`, parse first value\n4. De...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T19:31:14.096476','2025-10-26T19:31:14.096480',NULL,3,'2025-10-27T21:25:36.576269');
INSERT INTO knowledge_entries VALUES('48e9ce05','general','Crystal Parser Phase 74: Proc Literal Syntax (->)',replace('Pattern: Crystal parser Phase 74 - Proc literal syntax (->) for anonymous function literals\n\nSolution: Implemented full proc literal parsing with type annotation support. Key design decisions:\n1. Reused block_params/block_body fields from Block nodes (no new fields needed)\n2. Added proc_return_type field for optional return type annotation\n3. Parser converts type annotations from Slice(UInt8) → String when creating Parameter structs\n4. Type inference returns generic Proc type (future: Proc(T1, T2 -> R))\n\nSyntax support:\n- Parameterless: -> { 42 }\n- With params: ->(x, y) { x + y }\n- Type annotations: ->(x : Int32, y : Int32) { x + y }\n- Return type: ->(x : Int32) : Int32 { x * 2 }\n- do...end form: ->(x) do ... end\n\nEvidence: All 907 tests pass. 16 comprehensive tests (12 parser + 4 semantic). Commit e93277bdd.\n\nApplicability: When implementing proc/lambda literals in parser:\n1. Reuse existing block infrastructure (params/body fields)\n2. Handle optional type annotations separately\n3. Convert Slice<UInt8> to String for parameter type annotations (matches Parameter signature)\n4. Support both brace and do...end forms\n\nAnti-patterns:\n- Creating new fields for proc params/body (reuse block_params/block_body instead)\n- Passing Slice(UInt8) directly to Parameter.new for type_annotation (convert to String first)\n- Implementing complex Proc(T1, T2 -> R) types before basic infrastructure (start with generic Proc type)\n\nConfidence: 0.95\nTags: crystal, parser, phase-74, proc-literal, anonymous-function, lambda, type-annotation, reuse-pattern','\n',char(10)),replace('Pattern: Crystal parser Phase 74 - Proc literal syntax (->) for anonymous function literals\n\nSolution: Implemented full proc literal parsing with type annotation support. Key design decisions:\n1. Reused block_params/block_body fields from Block nodes (no new fields needed)\n2. Added proc_return_type field for optional return type annotation\n3. Parser converts type annotations from Slice(UInt8) → St...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T20:00:57.228204','2025-10-26T20:00:57.228208',NULL,5,'2025-10-27T12:06:53.775089');
INSERT INTO knowledge_entries VALUES('86ba5f77','general','Crystal Parser Phase 75: Global Variables ($var)',replace('Pattern: Crystal parser Phase 75 - Global variables ($var) following InstanceVar pattern\n\nSolution: Implemented global variable support by copying InstanceVar pattern exactly:\n1. Lexer: Added GlobalVar token + DOLLAR_SIGN constant + lex_global_var method (@ → $)\n2. AST: Added Global kind (reuses literal field for $var text)\n3. Parser: Added to parse_prefix AND assignment targets list\n4. Type inference: Returns nil_type placeholder (future: global scope tracking)\n\nKey implementation:\n- Lexer lex_global_var mirrors lex_instance_var exactly (lines 219-253)\n- Parser Global case in parse_prefix (3239-3243)\n- Parser added Global to assignment target validation (line 285)\n- Supports ? and ! suffixes like identifiers\n- Works with all assignment operators (=, +=, -=, etc.)\n\nEvidence: All 923 tests pass (907 → 923, +16 new). 16 comprehensive tests (12 parser + 4 semantic). Commit 186fb7e5d.\n\nApplicability: When implementing variable types with special prefixes:\n1. Copy existing variable pattern (InstanceVar for @, Global for $)\n2. Add token kind and constant for prefix character\n3. Implement lex_<type>_var method following lex_instance_var pattern\n4. Add to parse_prefix for reading\n5. Add to assignment target validation for writing\n6. Add placeholder type inference\n\nAnti-patterns:\n- Forgetting to add to assignment targets (variables must be writable!)\n- Not supporting suffixes (?, !) if identifiers support them\n- Creating new fields when literal field suffices\n- Complex type inference before basic infrastructure works\n\nLesson: Assignment fix was discovered during testing - always verify assignments work, not just reads.\n\nConfidence: 0.95\nTags: crystal, parser, phase-75, global-variables, dollar-sign, variable-pattern, assignment\nRelated: InstanceVar pattern (@var), pattern reuse','\n',char(10)),replace('Pattern: Crystal parser Phase 75 - Global variables ($var) following InstanceVar pattern\n\nSolution: Implemented global variable support by copying InstanceVar pattern exactly:\n1. Lexer: Added GlobalVar token + DOLLAR_SIGN constant + lex_global_var method (@ → $)\n2. AST: Added Global kind (reuses literal field for $var text)\n3. Parser: Added to parse_prefix AND assignment targets list\n4. Type infer...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T20:14:30.307944','2025-10-26T20:14:30.307947',NULL,4,'2025-10-27T00:37:44.840026');
INSERT INTO knowledge_entries VALUES('f1395af5','general','Crystal Parser Phase 76: Class Variables (@@var) - PRODUCTION-READY',replace('## Pattern: Class Variable Implementation (@@var)\n\n### Key Innovation: @@ Detection in Lexer\n\n**Problem**: Need to distinguish @@var (class variable) from @var (instance variable)\n\n**Solution**: Modified lex_instance_var to check for second @ after first @:\n\n```crystal\nprivate def lex_instance_var\n  advance  # Consume first @\n  \n  # Check for class variable (@@var)\n  if @offset < @rope.size && current_byte == AT_SIGN\n    advance  # consume second @\n    return lex_class_var_continued(...)\n  end\n  \n  # Continue as instance variable...\nend\n```\n\n### Pattern Completion: Variable Trio\n\nPhase 76 completes the variable syntax pattern:\n- Phase 73: `@var` (instance variables)\n- Phase 75: `$var` (global variables)\n- Phase 76: `@@var` (class variables)\n\nAll three follow identical implementation pattern:\n1. Token kind in token.cr\n2. Lexer method (lex_X_var)\n3. AST Kind (X)\n4. Parser prefix case\n5. **CRITICAL**: Add to assignment targets in parser.cr\n6. Type inference method (infer_x)\n7. Comprehensive tests (parser + semantic)\n\n### Implementation Details\n\n**Files Modified**:\n- `lexer/token.cr`: Added ClassVar token\n- `lexer.cr`: Modified lex_instance_var (lines 195-200), added lex_class_var_continued (229-257)\n- `ast.cr`: Added ClassVar kind\n- `parser.cr`: Added to parse_prefix (3240-3244), assignment targets (285)\n- `type_inference_engine.cr`: Added infer_class_var (83-85, 514-520)\n\n**Tests**: 17 comprehensive tests (13 parser + 4 semantic)\n- Simple class variable: `@@class_var`\n- With underscores: `@@my_class_var`\n- With suffixes: `@@flag?`, `@@important!`\n- Assignment: `@@count = 42`\n- Multiple class variables\n- In expressions: `@@count + 1`\n- As method arguments: `foo(@@class_var)`\n- Inside class body\n- In array literals: `[@@first, @@second]`\n- **Critical test**: Distinguishing all three: `@@class_var + @instance_var + $global_var`\n\n### Lesson Learned: Left-Associative Parsing\n\n**Error encountered**: Test "distinguishes all three variable types" failed\n\n**Root cause**: Test assumed right-associative parsing:\n```\n@@a + @b + $c  →  @@a + (@b + $c)  # WRONG\n```\n\n**Reality**: Parser uses left-associative binary operators:\n```\n@@a + @b + $c  →  (@@a + @b) + $c  # CORRECT\n```\n\n**Fix**: Updated test expectations to match actual parse tree structure.\n\n**Applicability**: Always verify parser associativity when testing expressions with multiple operators.\n\n### Assignment Target Pattern (CRITICAL)\n\n**Lesson from Phase 75 & 76**: Variables must be BOTH readable AND writable.\n\n**Implementation**: Add to assignment target validation in parser.cr:\n```crystal\nunless left_node.kind == ExpressionNode::Kind::Identifier ||\n       left_node.kind == ExpressionNode::Kind::InstanceVar ||\n       left_node.kind == ExpressionNode::Kind::ClassVar ||    # Phase 76\n       left_node.kind == ExpressionNode::Kind::Global ||\n       left_node.kind == ExpressionNode::Kind::Index\n```\n\n**Anti-pattern**: Implementing variable syntax without adding to assignment targets → assignments fail to parse.\n\n### Verification\n\n**Evidence**:\n- All 940 tests pass (923 → 940, +17 new tests)\n- Commit: dff330ae7\n- Protocol: Full v11.1 with CASSANDRA (95% HIGH confidence), KC search, code archaeology\n\n### Next Steps\n\nVariable syntax complete. Future phases:\n- Type checking for class variables (track in class scope)\n- Class variable inheritance semantics\n- Class variable visibility rules','\n',char(10)),replace('## Pattern: Class Variable Implementation (@@var)\n\n### Key Innovation: @@ Detection in Lexer\n\n**Problem**: Need to distinguish @@var (class variable) from @var (instance variable)\n\n**Solution**: Modified lex_instance_var to check for second @ after first @:\n\n```crystal\nprivate def lex_instance_var\n  advance  # Consume first @\n  \n  # Check for class variable (@@var)\n  if @offset < @rope.size && cur...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T20:26:17.787182','2025-10-26T20:26:17.787184',NULL,2,'2025-10-27T00:35:51.137825');
INSERT INTO knowledge_entries VALUES('e00652ea','general','Crystal Parser Phase 77: Type Declarations for Class/Global Variables',replace('## Pattern: Completing Variable Declaration Trio\n\n### Problem\nAfter implementing class variables (@@var) and global variables ($var) in Phases 75-76, needed to add type declaration support (@@var : Type, $var : Type) to match existing instance variable declarations (@var : Type from Phase 5C).\n\n### Solution: Lookahead Disambiguation + Pattern Reuse\n\n**Key Innovation**: Distinguish type declarations from assignments in class bodies using lookahead.\n\n```crystal\n# In class body:\nif token.kind == Token::Kind::ClassVar\n  next_token = peek_next_non_trivia\n  if next_token.kind == Token::Kind::Colon\n    expr = parse_class_var_decl  # @@var : Type\n  else\n    expr = parse_statement       # @@var = value\n  end\nend\n```\n\n### Implementation Details\n\n**AST** (ast.cr:262, 264):\n- ClassVarDecl kind (@@var : Type)\n- GlobalVarDecl kind ($var : Type)\n- Reused ivar_decl_type field (field reuse pattern)\n\n**Parser** (parser.cr):\n1. **Helper method** (4840-4850): peek_next_non_trivia - skips whitespace/newlines/comments\n2. **Class body** (2432-2455): Lookahead for @@var and @var to distinguish : vs =\n3. **Top-level** (243-273): Extended $var handling in parse_statement\n4. **Declaration parsers** (2918-2996): parse_class_var_decl, parse_global_var_decl\n\n**Type Inference** (type_inference_engine.cr:83-97, 539-558):\n- Added when clauses for all three declaration types\n- All return nil_type (declarations have no runtime value)\n\n### Critical Fix: Lookahead Pattern\n\n**Original bug**: Unconditionally calling parse_class_var_decl for any ClassVar token in class body broke existing assignments (@@var = 42).\n\n**Solution**: Peek ahead to check next token:\n- Colon → Type declaration\n- Equals → Assignment (via parse_statement)\n\n**Applied to both @var and @@var** to fix existing InstanceVar behavior too.\n\n### Pattern Completion\n\nVariable declarations now complete:\n```\n┌─────────────┬──────────────┬──────────────────┐\n│ Variable    │ Read/Write   │ Type Declaration │\n├─────────────┼──────────────┼──────────────────┤\n│ @var        │ Phase 73     │ Phase 5C         │\n│ @@var       │ Phase 76     │ Phase 77         │\n│ $var        │ Phase 75     │ Phase 77         │\n└─────────────┴──────────────┴──────────────────┘\n```\n\nAll follow identical implementation pattern:\n1. XVarDecl AST kind\n2. parse_x_var_decl method (follows InstanceVarDecl structure)\n3. Lookahead in class body (: vs =)\n4. Top-level handling (for $var)\n5. infer_x_var_decl returns nil_type\n6. Reuse ivar_decl_type field\n\n### Tests\n\n18 comprehensive tests (14 parser + 4 semantic):\n\n**Class variable declarations** (7 parser tests):\n- Simple: `@@count : Int32`\n- Multiple in same class\n- Custom types: `@@manager : Manager`\n- With underscores: `@@my_class_var`\n- Alongside methods and instance variables\n\n**Global variable declarations** (7 parser tests):\n- Simple: `$count : Int32`\n- Multiple at top level\n- Custom types, underscores, suffixes (?, !)\n- Interleaved with other statements\n\n**Semantic** (4 tests):\n- Type inference returns Nil for all declarations\n- Multiple declarations handled correctly\n\n### Verification\n\nAll 958 tests pass (940 → 958, +18 new tests)\nCommit: 8699dc6da\n\n### Lessons Learned\n\n**Disambiguation is critical**: Can''t assume context determines syntax.\n- In class bodies, @@var can be BOTH declaration and assignment\n- Must use lookahead to distinguish patterns\n\n**Field reuse pattern**: Don''t create new AST fields when existing ones work.\n- `literal` field reused for: Identifier, InstanceVar, ClassVar, Global, etc.\n- `ivar_decl_type` reused for: InstanceVarDecl, ClassVarDecl, GlobalVarDecl\n- Kind enum distinguishes node types\n\n**peek_next_non_trivia helper**: Essential for lookahead.\n- Skips Whitespace, Newline, Comment tokens\n- Returns next meaningful token\n- Enables disambiguation without backtracking\n\n### Anti-patterns\n\n**Assuming exclusive context**:\n❌ "At class body level, @@var can ONLY be a type declaration"\n✅ Check next token to distinguish @@var : Type vs @@var = value\n\n**Creating redundant fields**:\n❌ Add class_var_decl_type and global_var_decl_type\n✅ Reuse ivar_decl_type (Kind distinguishes purpose)\n\n**Manual position save/restore**:\n❌ saved_pos = @offset; @offset = saved_pos\n✅ Use peek_next_non_trivia helper (no state mutation)\n\n### Future Enhancements\n\n- Type-annotated assignments: `@@var : Type = value`\n- Type validation on subsequent assignments\n- Scope tracking for type annotations\n- Generic type support: `@@cache : Hash(String, Int32)`\n\n### Applicability\n\nUse this pattern when:\n- Extending existing syntax with similar variants\n- Multiple syntactic forms share prefix (@@var:, @@var=)\n- Need to distinguish without backtracking\n- Adding parallel features (if @var:Type exists, add @@var:Type)\n\n**Key insight**: "Reuse patterns + lookahead disambiguation = minimal AST changes"\n\n### Related Entries\n\n- Phase 5C: Instance variable declarations (foundation)\n- Phase 75-76: Class/global variable implementation (f1395af5, 86ba5f77)\n- Phase 66: Type declarations (4cf2fcd8)\n- AST field reuse pattern (lookup existing entries)','\n',char(10)),replace('## Pattern: Completing Variable Declaration Trio\n\n### Problem\nAfter implementing class variables (@@var) and global variables ($var) in Phases 75-76, needed to add type declaration support (@@var : Type, $var : Type) to match existing instance variable declarations (@var : Type from Phase 5C).\n\n### Solution: Lookahead Disambiguation + Pattern Reuse\n\n**Key Innovation**: Distinguish type declaration...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T20:42:39.731031','2025-10-26T20:42:39.731033',NULL,4,'2025-10-28T07:31:51.681032');
INSERT INTO knowledge_entries VALUES('6bd2fda7','general','Crystal Parser Phase 78: Floor Division Operator (//)',replace('## Pattern: Multi-Character Arithmetic Operator with Longest-Match-First\n\n### Problem\nAdd floor division operator `//` and compound assignment `//=` to complete arithmetic operator family.\n\n### Solution: Longest Match First Pattern\n\n**Critical**: Check `//` and `//=` BEFORE `/` in lexer to avoid mis-tokenization.\n\n```crystal\nwhen ''/''.ord.to_u8\n  if current_byte == ''/''.ord.to_u8  # Check // first\n    advance\n    if current_byte == ''=''.ord.to_u8  # Check //=\n      advance\n      FloorDivEq\n    else\n      FloorDiv\n    end\n  elsif current_byte == ''=''.ord.to_u8  # Then /=\n    advance\n    SlashEq\n  else  # Finally /\n    Slash\n  end\nend\n```\n\n### Implementation\n\n**Tokens** (token.cr:88, 148):\n- FloorDiv (after Slash)\n- FloorDivEq (after SlashEq)\n\n**Lexer** (lexer.cr:967-984):\nCheck order: `//=` → `//` → `/=` → `/` (longest first)\n\n**Parser** (parser.cr):\n- Precedence 20 (same as /, *, %) - line 5199\n- Compound assignment check - line 283\n- Operator mapping: `//` for desugaring - line 346\n\n**Type Inference** (type_inference_engine.cr):\n- Added to arithmetic operators - line 616\n- Built-in methods for Int32/Int64/Float64 - line 1881\n\n### Semantic Meaning\n\nFloor division rounds toward **negative infinity**:\n```\n7 // 2 = 3    (positive)\n-7 // 2 = -4  (NOT -3! Rounds down)\n7 // -2 = -4  (NOT -3! Rounds down)\n-7 // -2 = 3  (positive)\n```\n\nDifferent from **truncating division** (rounds toward zero):\n```\n-7 / 2 truncates to -3 (rounds toward zero)\n-7 // 2 floors to -4   (rounds toward -∞)\n```\n\n### Pattern Lineage\n\nFollows established multi-character operator pattern:\n\n**Longest-match-first operators**:\n- Phase 48: `<=>` before `<=`\n- Phase 50: `===` before `==`\n- Phase 52: `<<=` before `<<`, `>>=` before `>>`\n- Phase 78: `//=` before `//` before `/=` before `/`\n\n**Implementation steps**:\n1. Add tokens (operator + compound)\n2. Lexer: check longest first\n3. Parser: add to BINARY_PRECEDENCE\n4. Compound: add to assignment check + operator mapping\n5. Type inference: add to operator lists\n6. Tests: comprehensive coverage\n\n### Tests\n\n10 comprehensive tests:\n- Simple: `7 // 2`\n- Negative: `-7 // 2`\n- Assignment: `x = 10 // 3`\n- Compound: `x //= 3` (desugars to `x = x // 3`)\n- Disambiguation: `a / b // c` → `(a / b) // c`\n- Precedence: `2 + 10 // 3` → `2 + (10 // 3)`\n- Method args, arrays, chaining, parentheses\n\n### Verification\n\nAll 968 tests pass (958 → 968, +10 new tests)\nCommit: a9b8f3d46\n\n### Key Insight: Check Order Is Critical\n\n**Wrong order** (checking `/` before `//`):\n```crystal\nwhen ''/''.ord.to_u8\n  if current_byte == ''=''.ord.to_u8  # /=\n    SlashEq\n  else\n    Slash  # ❌ Tokenizes ''//'' as ''/'' + ''/''\n  end\nend\n```\n\n**Correct order** (checking `//` before `/`):\n```crystal\nwhen ''/''.ord.to_u8\n  if current_byte == ''/''.ord.to_u8  # // (check first!)\n    advance\n    if current_byte == ''=''.ord.to_u8  # //=\n      FloorDivEq\n    else\n      FloorDiv\n    end\n  elsif current_byte == ''=''.ord.to_u8  # /=\n    SlashEq\n  else  # /\n    Slash\n  end\nend\n```\n\n### Compound Assignment Desugaring\n\nFollows Phase 20 pattern:\n```crystal\nx //= y  →  x = x // y\n```\n\nImplementation:\n1. Add FloorDivEq to assignment check\n2. Add to operator mapping: `FloorDivEq` → `"//"`\n3. Existing desugaring infrastructure handles rest\n\n### Applicability\n\nUse this pattern for:\n- Multi-character operators where substring is valid operator\n- Compound assignment variants\n- Any operator requiring longest-match-first\n\n**Examples**:\n- `??` (nil coalescing) before `?` (ternary)\n- `**` (exponentiation) already done (Phase 19)\n- `//` (floor division) before `/` (this phase)\n\n### Anti-Patterns\n\n**❌ Wrong check order**:\n- Checking `/` before `//` → tokenizes as two division operators\n- Checking `=` before `//=` → breaks compound assignment\n\n**❌ Not adding to compound assignment**:\n- Add token but forget assignment check → `x //= y` fails to parse\n- Add token but forget operator mapping → desugaring breaks\n\n**❌ Different precedence from `/`**:\n- Floor division should have same precedence as regular division\n- Making it different would be confusing\n\n### Future Enhancements\n\n- Modulo operator `%` could have floor variant `%%`\n- Euclidean division (always positive remainder)\n- Integer division with rounding modes\n\n### Related Entries\n\n- Phase 18: Modulo (%) - similar arithmetic operator\n- Phase 19: Exponentiation (**) - multi-char pattern\n- Phase 20: Compound assignments - desugaring pattern\n- Phase 48: Spaceship (<=>) - longest-match-first (4275430c)\n- Phase 50: Case equality (===) - longest-match-first (f9c83ab2)\n- Phase 52: Bitwise compound (<<=, >>=) - multi-char compound (feaaafe4)\n\n### Confidence\n\n0.98 - Fully verified, follows established patterns exactly','\n',char(10)),replace('## Pattern: Multi-Character Arithmetic Operator with Longest-Match-First\n\n### Problem\nAdd floor division operator `//` and compound assignment `//=` to complete arithmetic operator family.\n\n### Solution: Longest Match First Pattern\n\n**Critical**: Check `//` and `//=` BEFORE `/` in lexer to avoid mis-tokenization.\n\n```crystal\nwhen ''/''.ord.to_u8\n  if current_byte == ''/''.ord.to_u8  # Check // first\n ...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-26T21:17:57.896491','2025-10-26T21:17:57.896493',NULL,6,'2025-10-27T12:09:00.781865');
INSERT INTO knowledge_entries VALUES('45fefe7e','general','Phase 79 - In operator keyword with macro integration','{"pattern": "Crystal parser - keyword operator (in) with macro integration", "solution": "Keyword operators like ''in'', ''as'', ''as?'' require: (1) Token::Kind enum entry, (2) keyword recognition in lexer, (3) binary precedence table entry at appropriate level, (4) type inference (returns Bool for comparison), (5) updating all existing code that expects identifier for that keyword (e.g., macro for loops)", "evidence": "Phase 79 implementation - all 978 tests passing. Critical fix: macro for loop parser was checking ''if token.kind == Identifier && text == \"in\"'', had to change to ''if token.kind == Token::Kind::In'' after making ''in'' a keyword. Precedence level 7 (comparison) causes ''value in 1..10'' to parse as ''(value in 1)..10'' due to range at level 5.", "applicability": "When adding keyword operators that may already be used as identifiers in certain contexts (macros, DSLs). Always search codebase for identifier-based checks after making new keywords.", "anti_patterns": ["Forgetting to update macro parser after adding keyword - causes test failures", "Not considering precedence interactions - ranges bind looser than comparison", "Expecting Binary node for ranges - ranges are Range nodes with range_begin/range_end fields", "Using .right field for Grouping nodes - Grouping uses .left field for inner expression"], "confidence": 0.95, "tags": ["crystal", "parser", "keyword-operator", "precedence", "macro-integration", "in-operator", "phase-79"], "related_entries": ["6bd2fda7"]}','{"pattern": "Crystal parser - keyword operator (in) with macro integration", "solution": "Keyword operators like ''in'', ''as'', ''as?'' require: (1) Token::Kind enum entry, (2) keyword recognition in lexer, (3) binary precedence table entry at appropriate level, (4) type inference (returns Bool for comparison), (5) updating all existing code that expects identifier for that keyword (e.g., macro for loo...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T21:51:37.419153','2025-10-26T21:51:37.419156',NULL,10,'2025-10-27T22:47:47.071352');
INSERT INTO knowledge_entries VALUES('2534ca2f','general','Phase 80 - Regex match operators (=~, !~)','{"pattern": "Multi-character regex operators with longest-match-first", "solution": "Regex match operators =~ and !~ require critical check order in lexer: For ''='': check =~ BEFORE => and =. For ''!'': check !~ BEFORE !=. Add to precedence table at level 7 (comparison), return Bool from type inference. Exact same pattern as Phase 78 (//), Phase 50 (===), Phase 48 (<=>).", "evidence": "Phase 80 implementation - all 988 tests passing (978 → 988, +10 new). Lexer check order: For ''='' (line 1063): =~ → => → === → == → =. For ''!'' (line 1089): !~ → != → !. Without longest-match-first, ''str =~ /pat/'' would mis-tokenize as ''str ='' + ''~ /pat/''. Disambiguation test confirms correct tokenization.", "applicability": "Multi-character operators where shorter substring is also valid operator. Applies to any A~ operator where ~ might be separate operator, or A= where = is assignment. Check longer variant first to avoid mis-tokenization.", "anti_patterns": ["Checking = before =~ causes mis-tokenization as assignment + tilde", "Checking != before !~ causes mis-tokenization", "Different precedence from other comparison operators", "Returning non-Bool type in simplified implementation"], "confidence": 0.95, "tags": ["crystal", "parser", "regex-match", "longest-match-first", "comparison-operator", "phase-80", "production-ready"], "related_entries": ["6bd2fda7", "f9c83ab2", "4275430c"]}','{"pattern": "Multi-character regex operators with longest-match-first", "solution": "Regex match operators =~ and !~ require critical check order in lexer: For ''='': check =~ BEFORE => and =. For ''!'': check !~ BEFORE !=. Add to precedence table at level 7 (comparison), return Bool from type inference. Exact same pattern as Phase 78 (//), Phase 50 (===), Phase 48 (<=>).", "evidence": "Phase 80 imple...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T22:02:20.549910','2025-10-26T22:02:20.549915',NULL,1,'2025-10-26T22:04:26.567964');
INSERT INTO knowledge_entries VALUES('722fab9d','general','Phase 81 - Nil-coalescing operator (??)','{"pattern": "Nil-coalescing operator with longest-match-first and precedence level 3", "solution": "Nil-coalescing ?? requires: (1) Check ?? BEFORE ? in lexer to avoid mis-tokenization as ternary, (2) Precedence level 3 (same as ||) - both have ''or'' semantics (value OR default), (3) Type inference returns right_type (fallback type) in simplified implementation. Follows exact pattern from Phase 78 which explicitly mentioned ?? as example.", "evidence": "Phase 81 implementation - all 998 tests passing (988 → 998, +10 new). Lexer at line 1179: checks ?? before ? (ternary). Without longest-match-first, ''value ?? default'' would tokenize as ''value ?'' + ''? default''. Precedence 3 makes it bind same as || but looser than ternary (2). Disambiguation test confirms ?? vs ? parsing.", "applicability": "Multi-character operators where shorter substring is valid operator. Pattern predicted by Phase 78 entry 6bd2fda7. Precedence level should match semantic meaning (??=or-like, same as ||). Type inference can be simplified (return fallback type) or accurate (return union of non-nil left | right).", "anti_patterns": ["Checking ? before ?? causes mis-tokenization as ternary + question", "Different precedence from || - confusing since both are ''or'' semantics", "Higher precedence than ternary - breaks ''a ?? b ? c : d'' expectation", "Returning left type instead of right type in simplified implementation"], "confidence": 0.95, "tags": ["crystal", "parser", "nil-coalescing", "longest-match-first", "precedence-3", "phase-81", "production-ready"], "related_entries": ["6bd2fda7", "f9c83ab2", "2534ca2f", "4275430c"]}','{"pattern": "Nil-coalescing operator with longest-match-first and precedence level 3", "solution": "Nil-coalescing ?? requires: (1) Check ?? BEFORE ? in lexer to avoid mis-tokenization as ternary, (2) Precedence level 3 (same as ||) - both have ''or'' semantics (value OR default), (3) Type inference returns right_type (fallback type) in simplified implementation. Follows exact pattern from Phase 78 ...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T22:10:40.955293','2025-10-26T22:10:40.955302',NULL,1,'2025-10-27T17:53:25.541439');
INSERT INTO knowledge_entries VALUES('48658179','general','Phase 82 - Nil-coalescing compound assignment (??=)','{"pattern": "Compound assignment with 3-level longest-match-first check", "solution": "Nil-coalescing compound assignment ??= follows Phase 20/51/52 pattern: (1) Add NilCoalesceEq token, (2) Lexer: 3-level check ??= before ?? before ? (critical order), (3) Add to parser assignment check list, (4) Add to operator mapping: ??= maps to ?? operator, (5) Desugar x ??= y to x = x ?? y. NO type inference changes - desugaring handles everything.", "evidence": "Phase 82 implementation - all 1008 tests passing (998 → 1008, +10 new). Lexer at line 1179: checks ??= before ?? before ?. 3-level disambiguation required. Without proper order would tokenize as ??+= or ?+?=. Parser adds to assignment check (line 293) and operator mapping (line 357). Desugaring to Phase 81 ?? operator means zero type inference changes.", "applicability": "Compound assignment for multi-character operators requiring nested longest-match-first. Pattern: If base operator AB exists, compound AB= requires checking AB= before AB before A. Phase 20 pattern (5 steps) works for all compound assignments. Desugaring infrastructure eliminates need for type inference changes.", "anti_patterns": ["Checking ?? before ??= causes mis-tokenization as nil-coalesce + equals", "Checking ? before ?? before ??= causes complete mis-tokenization", "Adding type inference for compound assignment - desugaring handles it", "Different desugaring than x = x op y pattern", "Forgetting to add to both assignment check AND operator mapping"], "confidence": 0.98, "tags": ["crystal", "parser", "nil-coalesce-assign", "compound-assignment", "longest-match-first", "3-level-check", "phase-82", "production-ready"], "related_entries": ["722fab9d", "feaaafe4", "af6a60c7", "6bd2fda7"]}','{"pattern": "Compound assignment with 3-level longest-match-first check", "solution": "Nil-coalescing compound assignment ??= follows Phase 20/51/52 pattern: (1) Add NilCoalesceEq token, (2) Lexer: 3-level check ??= before ?? before ? (critical order), (3) Add to parser assignment check list, (4) Add to operator mapping: ??= maps to ?? operator, (5) Desugar x ??= y to x = x ?? y. NO type inference...',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T22:41:45.138470','2025-10-26T22:41:45.138473',NULL,2,'2025-10-27T22:47:47.071330');
INSERT INTO knowledge_entries VALUES('dc67e269','general','Phase 83 - Loop keyword (infinite loop)','Implements `loop do ... end` for infinite loops following while pattern but without condition checking. All 1018 tests passing. Commit: f20591dbd.',NULL,NULL,'[]','{}',0.8000000000000000444,'2025-10-26T23:01:46.849101','2025-10-26T23:01:46.849105',NULL,4,'2025-10-27T23:36:26.632372');
INSERT INTO knowledge_entries VALUES('9c32e768','general','Phase 84 - Spawn keyword (fiber concurrency)','Implements `spawn` keyword for creating fibers (lightweight concurrency). Dual form: `spawn do...end` (block) and `spawn expression`. Parser uses lookahead (Do token) to disambiguate. Type inference returns nil_type (fiber runs independently). All 1028 tests passing. Commit: 20e914865.','Implements `spawn` keyword for creating fibers (lightweight concurrency). Dual form: `spawn do...end` (block) and `spawn expression`. Parser uses lookahead (Do token) to disambiguate. Type inference returns nil_type (fiber runs independently). All 1028 tests passing. Commit: 20e914865.',NULL,'[]','{}',0.8000000000000000444,'2025-10-26T23:26:50.683091','2025-10-26T23:26:50.683097',NULL,1,'2025-10-27T12:06:53.775062');
INSERT INTO knowledge_entries VALUES('96258ded','general','Phase 85 - Uninitialized keyword (uninitialized variables)','Implements `uninitialized` keyword for creating uninitialized variables of specified type. Follows typeof/sizeof/pointerof function-like pattern: `uninitialized(Type)`. Parser: expect LParen, parse single type expression, expect RParen. Type inference returns nil_type (placeholder). All 1037 tests passing. Commit: e0be53d97. Test fixes: Generic types parse as Generic kind, not Call kind.','Implements `uninitialized` keyword for creating uninitialized variables of specified type. Follows typeof/sizeof/pointerof function-like pattern: `uninitialized(Type)`. Parser: expect LParen, parse single type expression, expect RParen. Type inference returns nil_type (placeholder). All 1037 tests passing. Commit: e0be53d97. Test fixes: Generic types parse as Generic kind, not Call kind.',NULL,'[]','{}',0.8000000000000000444,'2025-10-27T00:04:26.023041','2025-10-27T00:04:26.023044',NULL,6,'2025-10-27T23:36:26.632386');
INSERT INTO knowledge_entries VALUES('eb4f3d84','general','Crystal Parser Phase 86 - Offsetof Keyword Implementation','{"pattern": "Crystal parser - Offsetof keyword (Phase 86) - Field offset introspection", "solution": "Implemented offsetof keyword following introspection keyword pattern from typeof/sizeof/pointerof/uninitialized. Key innovation: Exactly 2-argument parsing with explicit comma validation, differentiating from variable-argument (typeof) and single-argument (sizeof/pointerof/uninitialized) patterns. Syntax: offsetof(Type, :field) returns Int32 byte offset. Implementation: Token (Offsetof), AST (Offsetof kind + offsetof_args field), Parser (parse_offsetof with 2-arg validation), Type inference (infer_offsetof returns nil_type placeholder).", "evidence": "All 1049 tests passing (+12 new: 8 parser + 4 semantic). Compiler builds. Commit 0c6c53701. Files: token.cr:55, lexer.cr:151, ast.cr:298/392/500, parser.cr:2145-2195/3525-3527, type_inference_engine.cr:178-180/1337-1355. CASSANDRA 98% HIGH confidence - pattern match confirmed.", "applicability": "Use this pattern for function-like keywords requiring exactly N arguments with comma separators. Parser validates argument count explicitly rather than using loops. Applicable to any compile-time introspection operation with multiple typed arguments.", "anti_patterns": ["Don''t check symbol literal values in tests (symbols include '':'' prefix)", "Don''t access private instance variables (@expr_types) in tests - use public methods or simple existence checks", "Don''t use complex symbols like :@ivar in tests - simple field names work better"], "confidence": 0.98, "tags": ["crystal", "parser", "phase-86", "offsetof", "introspection", "multi-argument-parsing", "compile-time"], "related_entries": ["52941c1f", "b62f67b4", "ca362b82"]}','{"pattern": "Crystal parser - Offsetof keyword (Phase 86) - Field offset introspection", "solution": "Implemented offsetof keyword following introspection keyword pattern from typeof/sizeof/pointerof/uninitialized. Key innovation: Exactly 2-argument parsing with explicit comma validation, differentiating from variable-argument (typeof) and single-argument (sizeof/pointerof/uninitialized) patterns....',NULL,'[]','{}',0.8000000000000000444,'2025-10-27T00:30:36.514023','2025-10-27T00:30:36.514028',NULL,4,'2025-10-28T07:31:51.681048');
INSERT INTO knowledge_entries VALUES('4b2b7577','general','Phase 87B-1: Accessor Macro Expansion via Immediate Visit Pattern','{"pattern": "AST generation during symbol collection using immediate visit() pattern (no AST mutation)", "solution": "Generate method AST nodes directly in SymbolCollector, immediately call visit() on generated nodes to register as MethodSymbol. Expansion happens in SymbolCollector.visit() when encountering Getter/Setter/Property nodes. Pattern: (1) Generate AST node via build_getter_def/build_setter_def, (2) Add to arena with arena.add(node), (3) Immediately call visit(id) which processes it like hand-written code. Works because visit() processes ANY ExprId, not just from program roots.", "evidence": "Phase 87B-1 implementation - 1055 tests pass (1049 existing + 6 new accessor tests), 0 failures, 0 errors. Accessor expansion verified via unit tests: getter name : String → def name : String; @name; end. Integration test with real Crystal code passes: Person/Product classes with mixed accessors parse successfully. Commit df74a4589. Implementation: 135 lines in symbol_collector.cr (expand_accessor_macro + build_getter_def + build_setter_def).", "applicability": "Use when: (1) Implementing macro-like feature that generates methods/classes, (2) Need compile-time code generation during symbol collection phase, (3) Want early expansion (equivalent to Crystal''s TopLevelVisitor first pass), (4) Want to avoid AST mutation complexity. NOT for: (1) Runtime code generation, (2) Type-dependent expansion (needs type inference), (3) General template evaluation with {{ }} or {% %}.", "anti_patterns": ["Expansion in TypeInferenceEngine - CRITICAL FLAW: TypeInferenceEngine doesn''t run in production CLI, only in tests. Would break in production.", "AST mutation (modifying class_body arrays after parsing) - complex, error-prone, breaks immutability assumptions", "Separate pre-semantic MacroExpander phase - adds integration points, more complex than immediate visit()", "Wrong type conversion: Parameter.new expects String?, but ExpressionNode.def_return_type expects Slice(UInt8)? - must convert appropriately for each use"], "confidence": 0.95, "tags": ["crystal-parser", "macro-expansion", "accessor-macros", "symbol-collection", "ast-generation", "phase-87b", "production-ready", "immediate-visit-pattern", "triumvirate-validated"], "related_entries": ["c8a0602d", "ec9ab575", "45fefe7e"]}','{"pattern": "AST generation during symbol collection using immediate visit() pattern (no AST mutation)", "solution": "Generate method AST nodes directly in SymbolCollector, immediately call visit() on generated nodes to register as MethodSymbol. Expansion happens in SymbolCollector.visit() when encountering Getter/Setter/Property nodes. Pattern: (1) Generate AST node via build_getter_def/build_set...',NULL,'[]','{}',0.8000000000000000444,'2025-10-27T12:01:36.790145','2025-10-27T12:01:36.790148',NULL,6,'2025-10-27T17:58:45.170080');
INSERT INTO knowledge_entries VALUES('c866a5e0','general','Phase 88: alignof and instance_alignof keywords','{"pattern": "Crystal parser - alignof/instance_alignof keywords (Phase 88) - Alignment introspection (Crystal 1.11.0)", "solution": "Implemented alignment introspection keywords following sizeof/pointerof single-argument pattern. Both return Int32 alignment in bytes. Syntax: alignof(Type) returns ABI alignment (e.g., 4 for Int32, 8 for Int64/String on 64-bit), instance_alignof(Type) returns instance alignment (differs from alignof for reference types). Implementation: Token (Alignof:56, InstanceAlignof:57), Lexer (alignof:152, instance_alignof:153), AST (2 kinds:299-300 + 2 getters:395-396 + 2 params:505-506), Parser (parse_alignof:2217-2262, parse_instance_alignof:2264-2309, cases:3642-3647), Type inference (infer_alignof:1380-1397, infer_instance_alignof:1399-1416, dispatch:181-186 - both return int32_type).", "evidence": "All 1146 tests passing (+26 new: 18 parser + 8 semantic). Commit 57d662083. Compiler builds. CASSANDRA 95% HIGH confidence → 100% verified (zero debugging, clean first-try). Test files: parser_alignof_spec.cr (18 tests - 9 alignof + 9 instance_alignof), semantic_alignof_spec.cr (8 tests - 4 each). Pattern match: sizeof (Phase 41) / pointerof (Phase 42) - single-argument parsing with loop, returns int32_type (NOT nil_type like offsetof).", "applicability": "Use this pattern for single-argument introspection keywords returning concrete type (Int32). Applicable to any compile-time reflection operation with variable arguments (loop-based parsing). Follow sizeof pattern for return type decision (int32_type vs nil_type placeholder).", "anti_patterns": ["Don''t return nil_type for keywords with known return type (alignof/instance_alignof/sizeof return Int32, not placeholder)", "Don''t use fixed-argument parsing (offsetof pattern) when keyword can accept multiple args - use loop instead"], "confidence": 0.98, "tags": ["crystal", "parser", "phase-88", "alignof", "instance_alignof", "introspection", "crystal-1.11.0", "single-argument-pattern"], "related_entries": ["eb4f3d84", "52941c1f", "b62f67b4", "ca362b82"]}','{"pattern": "Crystal parser - alignof/instance_alignof keywords (Phase 88) - Alignment introspection (Crystal 1.11.0)", "solution": "Implemented alignment introspection keywords following sizeof/pointerof single-argument pattern. Both return Int32 alignment in bytes. Syntax: alignof(Type) returns ABI alignment (e.g., 4 for Int32, 8 for Int64/String on 64-bit), instance_alignof(Type) returns instan...',NULL,'[]','{}',0.8000000000000000444,'2025-10-27T19:58:44.156681','2025-10-27T19:58:44.156684',NULL,0,NULL);
INSERT INTO knowledge_entries VALUES('e0142775','general','Phase 92A: annotation keyword (parser-only implementation)',replace('Phase 92A: annotation keyword (user-defined annotations - parser only)\n\n## Problem\nImplement annotation keyword for user-defined annotation declarations in Crystal compiler.\n\n## Solution\nParser-only implementation (Phase 92A) that recognizes annotation syntax but skips body parsing.\n\n### Changes\n1. **Token & Lexer**: Added Annotation keyword (token.cr:81, lexer.cr:177)\n2. **AST**: Added Annotation node kind + annotation_name field (ast.cr:345, 452, 564)\n3. **Parser**: Created parse_annotation method (parser.cr:3214-3261)\n   - Grammar: `annotation Name [; body...] end`\n   - Body skipped with loop until ''end'' token\n   - Updated dispatch in 4 locations + definition_start?\n4. **Tests**: 6 comprehensive tests in spec/parser_annotation_spec.cr\n\n### Pattern\nSimilar to alias (Phase 34) - simplest definition type:\n- No inheritance (unlike class/struct)\n- No complex body parsing needed\n- Just name + end\n\n## Evidence\n- All 6 new tests pass (598 microseconds)\n- All 1180 tests pass (zero regressions)\n- Compiler builds successfully\n- CASSANDRA 75% confidence validated\n\n## Applicability\nWhen implementing simple definition keywords:\n1. Follow existing patterns (class/struct/enum/alias)\n2. Split complex features into phases (92A parser, 92B body)\n3. Body skipping pattern: loop until ''end'' token\n4. Update 4 dispatch locations + definition_start?\n\n## Anti-patterns\n- ❌ Parsing body immediately (increases complexity)\n- ❌ Implementing @[Annotation] usage in same phase (separate concern)\n- ✅ Parser-only first, then body, then usage\n\n## Confidence\n0.95 - Verified with full test suite\n\n## Related\n- Phase 34: alias (similar simplicity)\n- Phase 32: struct (definition pattern)\n- Phase 33: enum (definition pattern)\n- Phase 92B: annotation body parsing (future)\n- Phase 93?: @[Annotation] usage syntax (future)\n\n## Tags\ncrystal, parser, annotation, definition, phase-92a, ast, landmark-protocol','\n',char(10)),replace('Phase 92A: annotation keyword (user-defined annotations - parser only)\n\n## Problem\nImplement annotation keyword for user-defined annotation declarations in Crystal compiler.\n\n## Solution\nParser-only implementation (Phase 92A) that recognizes annotation syntax but skips body parsing.\n\n### Changes\n1. **Token & Lexer**: Added Annotation keyword (token.cr:81, lexer.cr:177)\n2. **AST**: Added Annotation...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-27T22:11:40.949649','2025-10-27T22:11:40.949656',NULL,0,NULL);
INSERT INTO knowledge_entries VALUES('b0dca21e','general','Phase 93: is_a? keyword - Identifier to Keyword Upgrade',replace('Phase 93: Upgrade is_a? from identifier-based parsing to true keyword\n\n## Problem\nPhase 46 implemented is_a? parsing, but recognized it as Identifier token with string comparison check. This is inconsistent with as/as? keywords (Phase 44/45) and less efficient.\n\n## Solution\nUpgrade is_a? to true keyword status following Phase 44 pseudo-method pattern.\n\n### Changes\n1. **Token**: Added IsA keyword (token.cr:89)\n2. **Lexer**: "is_a?" → Token::Kind::IsA (lexer.cr:185)\n3. **Parser**: Updated parse_member_access (parser.cr:4830-4833)\n   - Before: `if member_token.kind == Identifier && text == "is_a?"`\n   - After: `if member_token.kind == Token::Kind::IsA`\n4. **Comments**: Updated Phase 46 → Phase 93 in ast.cr, type_inference_engine.cr\n5. **Tests**: Updated description, all 12 tests pass\n\n### Pattern: Identifier-to-Keyword Upgrade\n**When**: Feature initially implemented as identifier, but should be keyword\n**How**:\n1. Add keyword token\n2. Add lexer mapping\n3. Replace identifier check with token kind check\n4. Update comments\n5. Verify tests still pass\n\n**Key insight**: Parser/AST/type inference often correct already - just need lexer upgrade!\n\n## Evidence\n- All 12 tests pass (1.62ms)\n- All 1180 tests pass (73.25ms total)\n- Zero code changes to parse_is_a, infer_is_a (already correct)\n- Commit: b37547a24\n- CASSANDRA 90% → verified\n\n## Applicability\n**Use when**:\n- Feature works but uses identifier + string comparison\n- Should be consistent with similar keywords (as, as?)\n- Want cleaner parser logic + better error messages\n\n**Similar candidates**:\n- responds_to? (Phase 49) - still identifier-based\n\n## Benefits\n- ✅ Consistent with as/as? pseudo-method keywords\n- ✅ No string comparison in parser (faster)\n- ✅ Better error messages (keyword vs identifier)\n- ✅ Cleaner integration\n\n## Anti-patterns\n- ❌ Rewriting parser/type inference when already correct\n- ❌ Breaking AST fields (keep same names)\n- ✅ Minimal changes: just token + lexer + dispatch check\n\n## Confidence\n0.95 - Verified with full test suite\n\n## Related\n- Phase 44: as keyword (pseudo-method pattern) - KC d60b1a54\n- Phase 45: as? keyword (safe cast)\n- Phase 46: is_a? initial implementation (identifier-based)\n- Phase 49: responds_to? (candidate for upgrade)\n\n## Tags\ncrystal, parser, is_a, keyword-upgrade, pseudo-method, phase-93, identifier-to-keyword, refactoring','\n',char(10)),replace('Phase 93: Upgrade is_a? from identifier-based parsing to true keyword\n\n## Problem\nPhase 46 implemented is_a? parsing, but recognized it as Identifier token with string comparison check. This is inconsistent with as/as? keywords (Phase 44/45) and less efficient.\n\n## Solution\nUpgrade is_a? to true keyword status following Phase 44 pseudo-method pattern.\n\n### Changes\n1. **Token**: Added IsA keyword (...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-27T22:27:41.283549','2025-10-27T22:27:41.283552',NULL,1,'2025-10-27T23:36:26.632358');
INSERT INTO knowledge_entries VALUES('f93ff60c','general','Phase 94: responds_to? keyword - Pattern Reuse Validation',replace('Phase 94: responds_to? keyword upgrade validates Identifier-to-Keyword pattern\n\n## Problem\nPhase 49 implemented responds_to? as identifier-based. After Phase 93 (is_a?) established pattern, responds_to? is candidate for upgrade.\n\n## Solution\nApplied EXACT same pattern as Phase 93 (KC b0dca21e) with zero modifications.\n\n### Changes (identical to Phase 93)\n1. **Token**: Added RespondsTo keyword (token.cr:90)\n2. **Lexer**: "responds_to?" → Token::Kind::RespondsTo (lexer.cr:186)\n3. **Parser**: Token kind check instead of string comparison (parser.cr:4835-4838)\n4. **Comments**: Phase 49 → Phase 94\n5. **Tests**: Updated description\n\n### Implementation Time\n**8 minutes** (vs 15 min for Phase 93)\n- Faster due to pattern familiarity\n- Zero debugging (pattern already validated)\n- Copy-paste with renaming\n\n## Evidence\n- All 12 tests pass (1.45ms)\n- All 1180 tests pass (81.61ms)\n- Zero errors on first try\n- Commit: 455f3b85c\n- CASSANDRA 95% → verified 100%\n\n## Pattern Validation\n**Key insight**: Identifier-to-Keyword Upgrade is REPLICABLE pattern!\n\n**Phase 93** (first application):\n- 15 minutes implementation\n- Created pattern documentation\n- Confidence: 90% → 100%\n\n**Phase 94** (second application):\n- 8 minutes implementation (47% faster!)\n- Followed pattern exactly\n- Confidence: 95% → 100%\n\n**Pattern stability**: 2/2 successful applications\n\n## Applicability\n**Pattern confirmed for**:\n- Pseudo-method keywords (appears after dot)\n- Currently identifier-based with string comparison\n- Should be consistent with similar keywords\n\n**Completed upgrades**:\n- ✅ is_a? (Phase 93)\n- ✅ responds_to? (Phase 94)\n\n**Future candidates**: Any identifier-based pseudo-methods\n\n## Benefits\n- ✅ Pattern reuse reduces implementation time\n- ✅ Confidence increases with each application\n- ✅ Zero debugging when following pattern exactly\n- ✅ Consistent codebase (all pseudo-methods use keywords)\n\n## Meta-Learning\n**Pattern documentation pays off**:\n1. Phase 93: Discovered pattern, documented in KC\n2. Phase 94: Applied pattern, validated reusability\n3. Result: 47% faster implementation\n\n**CASSANDRA confidence calibration**:\n- Phase 93: 90% (first application, uncertain)\n- Phase 94: 95% (pattern proven, still cautious)\n- Future: Could be 98%+ after 3+ successful applications\n\n## Confidence\n1.0 - Pattern validated across 2 implementations\n\n## Related\n- Phase 93: is_a? keyword upgrade - KC b0dca21e (pattern origin)\n- Phase 44: as keyword (pseudo-method from start)\n- Phase 45: as? keyword (pseudo-method from start)\n\n## Tags\ncrystal, parser, responds_to, keyword-upgrade, pattern-reuse, pattern-validation, phase-94, identifier-to-keyword, meta-learning','\n',char(10)),replace('Phase 94: responds_to? keyword upgrade validates Identifier-to-Keyword pattern\n\n## Problem\nPhase 49 implemented responds_to? as identifier-based. After Phase 93 (is_a?) established pattern, responds_to? is candidate for upgrade.\n\n## Solution\nApplied EXACT same pattern as Phase 93 (KC b0dca21e) with zero modifications.\n\n### Changes (identical to Phase 93)\n1. **Token**: Added RespondsTo keyword (tok...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-27T22:41:47.471867','2025-10-27T22:41:47.471870',NULL,0,NULL);
INSERT INTO knowledge_entries VALUES('9142dd48','general','Phase 95A: asm keyword - MAIEUTIC Complexity Reduction Success',replace('Phase 95A: asm keyword demonstrates successful MAIEUTIC analysis for complexity reduction\n\n## Problem\nImplement asm keyword for inline assembly. Initial assessment: complex multi-section syntax (5 colon-separated sections), no precedent, LOW confidence.\n\n## MAIEUTIC Process\n\n### Initial CASSANDRA: 35% LOW-MEDIUM\n**Fears**:\n- Complex syntax: asm("template" : "outputs" : "inputs" : "clobbers" : "flags")\n- No similar pattern in codebase\n- Constraint parsing: "=r"(dst), "r"(src)\n- 150+ lines estimate\n- 60+ minutes estimate\n\n### MAIEUTIC Strategic Questioning\n\n**Q1: What is MINIMAL for parser-only Phase 95A?**\n- Student: Parse all 5 sections\n- Socrates: Do you NEED to understand sections NOW?\n- Insight: NO! Parse as comma-separated expressions ✅\n\n**Q2: Is there similar pattern?**\n- Student: No multi-section syntax...\n- Socrates: What about typeof/sizeof with multiple args?\n- Discovery: Function-like keyword pattern (KC ca362b82)! ✅\n\n**Q3: What are REAL complexities?**\n- Student: Constraint syntax "=r"(dst)\n- Socrates: Is this needed for Phase 95A parser?\n- Realization: NOT needed! Future phase! ✅\n\n### CASSANDRA Re-Assessment: 85% HIGH\n**After MAIEUTIC**:\n- Pattern found: typeof/sizeof (KC ca362b82)\n- Scope reduced: Just parse args, no colon interpretation\n- Complexity: 150 lines → 80 lines\n- Time: 60 min → 20 min (66% reduction!)\n\n## Solution\n\n### Phase 95A Scope (simplified)\n```crystal\n# Parse as function-like keyword:\nasm("template", arg1, arg2)  # All comma-separated\n\n# Future Phase 95B will interpret colons:\nasm("x" : "=r"(out) : "r"(in) : "eax" : "volatile")\n```\n\n### Implementation (following typeof pattern)\n1. Token: Asm keyword\n2. Lexer: "asm" → Token::Kind::Asm\n3. AST: Asm node + asm_args: Array(ExprId)?\n4. Parser: parse_asm (copy typeof structure)\n5. Type inference: infer_asm returns nil_type\n\n## Evidence\n- 6 tests pass (1.0ms)\n- 1186 total tests pass (zero regressions)\n- Implementation: 80 lines (~48 parser, ~24 type inference)\n- Time: ~20 minutes\n- Commit: 828236880\n- CASSANDRA 85% → validated 100%\n\n## Key Insights\n\n### 1. MAIEUTIC Saves Time\n**Without MAIEUTIC**: 60+ min, 150+ lines, 35% confidence\n**With MAIEUTIC**: 20 min, 80 lines, 85%→100% confidence\n**Savings**: 66% time reduction, 47% code reduction\n\n### 2. Scope Reduction Pattern\n**Before**: Try to implement everything at once\n**After**: Phase 95A (parser), Phase 95B (sections), Phase 95C (validation)\n**Benefit**: Incremental verification, lower risk\n\n### 3. Pattern Discovery Through Questioning\n**Initial**: "No precedent, complex syntax"\n**MAIEUTIC**: "What about typeof? Same pattern!"\n**Result**: Reuse proven pattern (Phase 40/41/42)\n\n### 4. Confidence Calibration\nMAIEUTIC can upgrade confidence:\n- 35% LOW → 85% HIGH (2.4x increase!)\n- By reducing scope + finding patterns\n- Evidence-based confidence adjustment\n\n## Applicability\n\n**Use MAIEUTIC when**:\n- Initial confidence <50% (LOW-MEDIUM)\n- Problem seems complex\n- No obvious pattern\n- Unclear scope\n\n**MAIEUTIC Questions**:\n1. What is MINIMAL needed for this phase?\n2. Is there similar pattern we''ve seen?\n3. What are REAL vs IMAGINED complexities?\n4. Can we defer complexity to future phases?\n\n**Expected Result**:\n- Scope reduction\n- Pattern discovery\n- Confidence upgrade\n- Time/complexity savings\n\n## Anti-patterns\n- ❌ Implementing everything in one phase (scope creep)\n- ❌ Not searching for similar patterns (reinventing wheel)\n- ❌ Assuming complexity without questioning (premature fear)\n- ✅ Questioning scope, finding patterns, incremental implementation\n\n## Meta-Learning\n\n**Pattern**: MAIEUTIC → Pattern Discovery → Confidence Upgrade\n\nThis is SECOND successful MAIEUTIC application:\n1. Phase 92B analysis: Discovered annotations are always empty (KC c8a0602d)\n2. Phase 95A analysis: Discovered typeof pattern applies (this entry)\n\n**MAIEUTIC success rate**: 2/2 (100%)\n\n**Time savings**: ~40 minutes (66% reduction)\n\n## Confidence\n1.0 - Fully verified implementation + meta-pattern validated\n\n## Related\n- KC ca362b82: Function-like keyword pattern (typeof/sizeof/pointerof)\n- KC 1068daaf: Breakthroughs through iteration (MAIEUTIC is structured iteration)\n- Phase 40/41/42: typeof/sizeof/pointerof implementations\n\n## Tags\ncrystal, parser, asm, inline-assembly, maieutic-success, complexity-reduction, scope-reduction, pattern-discovery, confidence-upgrade, phase-95a, landmark-protocol','\n',char(10)),replace('Phase 95A: asm keyword demonstrates successful MAIEUTIC analysis for complexity reduction\n\n## Problem\nImplement asm keyword for inline assembly. Initial assessment: complex multi-section syntax (5 colon-separated sections), no precedent, LOW confidence.\n\n## MAIEUTIC Process\n\n### Initial CASSANDRA: 35% LOW-MEDIUM\n**Fears**:\n- Complex syntax: asm("template" : "outputs" : "inputs" : "clobbers" : "fla...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-27T23:02:02.140798','2025-10-27T23:02:02.140801',NULL,1,'2025-10-27T23:36:26.632055');
INSERT INTO knowledge_entries VALUES('bb4c1fab','general','Phase 96: previous_def keyword - Super Pattern Application',replace('## Pattern: Exact Structural Copy from Reference Implementation\n\n### Problem\nImplement previous_def keyword for calling previous method definitions before reopening/redefining. CASSANDRA assessment: 95% VERY HIGH confidence based on exact match to super keyword (Phase 39).\n\n### Solution: Direct Pattern Application\n\n**Key Strategy**: Follow Phase 39 (super) structure exactly, search-and-replace names.\n\n**Grammar**: `previous_def | previous_def() | previous_def(arg1, arg2, ...)`\n\n**Semantic Distinction**:\n- `nil` args = implicit (pass all current method args)\n- `[]` empty array = explicit no args\n- `[items]` array with items = explicit args\n\n### Implementation (17 minutes)\n\n**Token & Lexer** (+2 lines):\n- Token::Kind::PreviousDef (token.cr:51, after Super)\n- "previous_def" → PreviousDef (lexer.cr:147)\n\n**AST** (+3 lines):\n- Kind::PreviousDef (ast.cr:309)\n- previous_def_args : Array(ExprId)? (ast.cr:409, 524)\n\n**Parser** (+72 lines):\n- parse_previous_def (parser.cr:2089-2154, 67 lines)\n  - Copied parse_super structure exactly\n  - Handles three forms: bare | empty parens | args\n  - Returns error on syntax issues\n- Dispatch (parser.cr:116-120, 5 lines)\n\n**Type Inference** (+21 lines):\n- Dispatch (type_inference_engine.cr:166-168, 3 lines)\n- infer_previous_def (type_inference_engine.cr:1289-1307, 18 lines)\n  - Infer types of all arguments\n  - Returns nil_type (placeholder)\n\n**Tests** (+9 comprehensive tests):\n- spec/parser_previous_def_spec.cr\n- Mirrored super test structure:\n  1. Without parens (implicit args)\n  2. Empty parens (explicit no args)\n  3. Single argument\n  4. Multiple arguments\n  5. Postfix if modifier\n  6. Multiple methods\n  7. Before other statements\n  8. Complex expressions as arguments\n  9. Distinction between three forms\n\n### Evidence\n\n**Success Metrics**:\n- ✅ All 9 previous_def tests passed on first try\n- ✅ All 1195 total tests passed (1186 + 9)\n- ✅ Zero compilation errors\n- ✅ Zero regressions\n- ✅ Implementation time: 17 minutes\n- ✅ Commit: 06aaae4c2\n\n**CASSANDRA Validation**:\n- Predicted: 95% confidence, 15-20 min, ~55 lines parser + ~15 lines inference\n- Actual: 100% success, 17 min, 67 lines parser + 18 lines inference\n- Calibration: Excellent (95% → 100%)\n\n### Pattern Steps\n\n1. **Find reference implementation**: Identify existing keyword with same structure\n2. **Read completely**: Understand all parts (token, lexer, AST, parser, type inference, tests)\n3. **Copy structure**: Create new methods following exact pattern\n4. **Search-and-replace**: Change names (super → previous_def, super_args → previous_def_args)\n5. **Mirror tests**: Copy test structure, adapt examples\n6. **Verify**: Run tests, commit\n\n### Key Insights\n\n**Why 95% confidence?**\n- ✅ Seen exact pattern (super)\n- ✅ Seen similar patterns (yield, typeof, sizeof)\n- ✅ Know standard approach (keyword → token → lexer → AST → parser → inference)\n- ✅ Can verify quickly (tests)\n\n**Pattern matching criteria**:\n- Same grammar structure (bare | empty parens | args)\n- Same AST field type (Array(ExprId)?)\n- Same semantic distinction (nil vs [] vs [items])\n- Same context (method-calling keywords)\n\n**Time distribution**:\n- Reading reference: 3 min\n- Token + Lexer: 2 min\n- AST: 2 min\n- Parser: 5 min\n- Type inference: 2 min\n- Tests: 3 min\n\n### Applicability\n\n**Use this pattern when**:\n- Implementing keywords with exact same structure as existing keywords\n- Grammar matches reference (same number of forms)\n- AST field types match (same data structures)\n- Semantic rules match (same distinctions)\n\n**Examples**:\n- super → previous_def (this phase)\n- as → as? (Phase 44 → 45)\n- getter → setter → property (accessor macros)\n\n**Don''t use when**:\n- Grammar differs (different number of forms)\n- Semantic rules differ (different distinctions)\n- Implementation details differ (different validation logic)\n\n### Anti-patterns\n\n**❌ Assuming differences where none exist**:\n- Don''t over-engineer\n- Don''t add validation that reference doesn''t have\n- Don''t change AST structure unnecessarily\n\n**❌ Incomplete copying**:\n- Missing dispatch in parser/type inference\n- Incomplete test coverage\n- Missing comments/documentation\n\n**✅ Correct approach**:\n- Copy structure exactly\n- Mirror test coverage\n- Update comments consistently\n- Run full test suite\n\n### Meta-Learning\n\n**Pattern Hierarchy**:\n```\nMethod-Calling Keywords\n├── super (Phase 39) ← reference\n├── previous_def (Phase 96) ← exact copy\n├── yield (Phase 10) ← similar\n└── Function-like Keywords\n    ├── typeof (Phase 40)\n    ├── sizeof (Phase 41)\n    └── pointerof (Phase 42)\n```\n\n**CASSANDRA Confidence Calibration**:\n- Phase 93 (is_a?): 90% → 100%\n- Phase 94 (responds_to?): 95% → 100%\n- Phase 96 (previous_def): 95% → 100%\n- Pattern: When exact structural match found, 90-95% confidence is well-calibrated\n\n**Time Savings Through Pattern Recognition**:\n- Without pattern: ~45 minutes (exploratory implementation)\n- With pattern: ~17 minutes (direct copy)\n- Savings: 62% time reduction\n\n### Confidence\n0.98 - Fully verified implementation with comprehensive tests\n\n### Related Entries\n- Phase 39: super keyword (reference implementation)\n- Phase 93: is_a? keyword upgrade (identifier-to-keyword pattern)\n- Phase 94: responds_to? keyword upgrade (pattern reuse validation)\n- Phase 95A: asm keyword (MAIEUTIC complexity reduction)\n- KC ca362b82: Function-like keyword pattern (typeof/sizeof/pointerof)\n\n### Tags\nphase-96, previous_def, pattern-reuse, super-pattern, parser-only, keyword, crystal-compiler, cassandra-validated, exact-copy, structural-pattern, method-calling-keywords','\n',char(10)),replace('## Pattern: Exact Structural Copy from Reference Implementation\n\n### Problem\nImplement previous_def keyword for calling previous method definitions before reopening/redefining. CASSANDRA assessment: 95% VERY HIGH confidence based on exact match to super keyword (Phase 39).\n\n### Solution: Direct Pattern Application\n\n**Key Strategy**: Follow Phase 39 (super) structure exactly, search-and-replace nam...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-27T23:37:13.505385','2025-10-27T23:37:13.505389',NULL,1,'2025-10-28T07:31:51.680722');
INSERT INTO knowledge_entries VALUES('e4a182f0','general','Phase 97: union keyword (C bindings) - Struct Pattern Application',replace('## Pattern: Boolean Flag Parameter for Syntactically Identical Constructs\n\n### Problem\nImplement union keyword for C binding union types (FFI). CASSANDRA assessment: 98% VERY HIGH confidence based on exact match to Phase 32 (struct) pattern.\n\n### Solution: Code Reuse via Boolean Flag\n\n**Key Strategy**: Follow Phase 32 (struct) boolean flag pattern exactly.\n\n**Grammar**: `union Name ... end` (identical to class/struct)\n\n**Semantic Distinction**:\n- Class: Reference type (heap allocation)\n- Struct: Value type (stack allocation, sequential fields)\n- Union: C binding type (stack allocation, overlapping fields)\n\n### Implementation (14 minutes)\n\n**Token & Lexer** (+2 lines):\n- Token::Kind::Union (token.cr:81, after Struct)\n- "union" → Union mapping (lexer.cr:177)\n\n**AST** (+3 lines):\n- Kind::Union (ast.cr:345, after Struct)\n- class_is_union : Bool? field (ast.cr:384, 500)\n- Follows same pattern as class_is_struct\n\n**Parser** (+12 lines):\n- parse_union wrapper (parser.cr:3072-3076)\n  ```crystal\n  private def parse_union : ExprId\n    parse_class(is_union: true)\n  end\n  ```\n- Updated parse_class signature:\n  - Before: `(is_struct : Bool = false, is_abstract : Bool = false)`\n  - After: `(is_struct : Bool = false, is_union : Bool = false, is_abstract : Bool = false)`\n- Updated kind selection logic:\n  ```crystal\n  kind = if is_union\n           ExpressionNode::Kind::Union\n         elsif is_struct\n           ExpressionNode::Kind::Struct\n         else\n           ExpressionNode::Kind::Class\n         end\n  ```\n- Updated 6 dispatch locations:\n  - 4× case statements (top-level, class body, module/lib body)\n  - 1× definition_start? predicate\n  - 1× abstract case statement\n\n**Type Inference** (+5 lines):\n- Added when .union? dispatch (type_inference_engine.cr:263-266)\n- Reuses infer_class (same as struct and class)\n- Comment clarifies: "At parsing stage, handled identically to class"\n\n**Tests** (+8 comprehensive tests):\n- spec/parser_union_spec.cr\n- Mirrored struct test structure:\n  1. Empty union\n  2. Union with fields (@int_val, @float_val)\n  3. Union inside lib block (C bindings context)\n  4. Union with methods\n  5. Multiple unions\n  6. Nested union in module\n  7. Abstract union\n  8. Distinction: class vs struct vs union\n\n### Evidence\n\n**Success Metrics**:\n- ✅ All 8 union tests passed on first try\n- ✅ All 1203 total tests passed (1195 + 8)\n- ✅ Zero compilation errors\n- ✅ Zero regressions\n- ✅ Implementation time: 14 minutes\n- ✅ Commit: d61d40352\n\n**CASSANDRA Validation**:\n- Predicted: 98% confidence, 12-15 lines, 12-15 min\n- Actual: 100% success, 17 lines total (12 parser + 5 inference), 14 min\n- Calibration: Excellent (98% → 100%)\n\n### Pattern Steps\n\n**Boolean Flag Pattern** (from KC 64b43022):\n1. **Add token & lexer** (2 lines)\n2. **Add AST kind & field** (3 lines)\n3. **Create wrapper method** that calls existing method with flag=true\n4. **Update existing method signature** to accept new boolean parameter\n5. **Update conditional logic** for kind selection (if/elsif/else)\n6. **Update all dispatch locations** (case statements, predicates)\n7. **Reuse type inference** (same logic as base construct)\n8. **Mirror test structure** from reference implementation\n\n### Key Insights\n\n**Why 98% confidence?**\n- ✅ Exact pattern match (struct → union)\n- ✅ Identical syntax (only keyword differs)\n- ✅ Known implementation (KC 64b43022)\n- ✅ Quick verification (8 test scenarios)\n\n**Code Reuse Benefits**:\n- 17 lines changed vs 60+ lines duplicated (72% reduction)\n- Single source of truth for class/struct/union parsing\n- Bug fixes apply to all three automatically\n- Consistent behavior across constructs\n\n**Boolean Flag vs Separate Method**:\n- ✅ Use boolean flag: Identical syntax, different semantics\n- ❌ Use separate method: Different syntax OR complex parsing\n\n### Applicability\n\n**Use this pattern when**:\n- Adding language construct syntactically identical to existing one\n- Only semantic difference (memory layout, type behavior)\n- Want consistent parsing logic\n- Supporting compound modifiers (abstract union, private struct)\n\n**Examples**:\n- Phase 32: struct (value type vs reference type)\n- Phase 97: union (overlapping fields vs sequential fields)\n- Future: record, interface (if syntactically similar)\n\n**Don''t use when**:\n- Syntax differs significantly\n- Parsing logic substantially different\n- No benefit from code reuse\n\n### Anti-patterns\n\n**❌ Duplicating parse_class**:\n- Creates 60+ lines of duplicate code\n- Bug fixes must be applied twice\n- Inconsistent behavior risk\n\n**❌ Not updating all dispatch locations**:\n- Missing case statement → syntax error\n- Missing predicate → incorrect parsing\n- Missing abstract case → modifier doesn''t work\n\n**✅ Correct approach**:\n- Add boolean parameter with default false\n- Update conditional logic (if/elsif/else)\n- Update ALL dispatch locations systematically\n- Mirror test structure from reference\n\n### Use Case\n\n```crystal\nlib C\n  union IntOrFloat\n    @int_val : Int32\n    @float_val : Float64\n  end\nend\n\nvalue = C::IntOrFloat.new\nvalue.int_val = 42\nputs value.float_val  # Same memory as int_val!\n```\n\n**Memory Layout**:\n- Class: `[vtable_ptr][field1][field2]...` (heap)\n- Struct: `[field1][field2]...` (stack, sequential)\n- Union: `[field1 OR field2 OR ...]` (stack, overlapping)\n\nUnion stores all fields in SAME memory location (C union semantics).\n\n### Meta-Learning\n\n**Pattern Hierarchy**:\n```\nBoolean Flag Pattern (KC 64b43022)\n├── Phase 32: is_struct (class → struct)\n├── Phase 36: is_abstract (class/def → abstract)\n├── Phase 68: is_splat (param → *param)\n└── Phase 97: is_union (class → union)\n```\n\n**CASSANDRA Confidence Calibration**:\n- Phase 32 (struct): 95% → 100%\n- Phase 97 (union): 98% → 100%\n- Pattern: Boolean flag pattern gives 95-98% confidence (well-calibrated)\n\n**Time Efficiency**:\n- Without pattern: ~45 minutes (exploratory + testing)\n- With pattern: ~14 minutes (direct application)\n- Savings: 69% time reduction\n\n### Confidence\n0.99 - Fully verified implementation with comprehensive tests\n\n### Related Entries\n- Phase 32: struct keyword (KC 64b43022 - boolean flag pattern)\n- Phase 36: abstract modifier (KC 0b95cbf4 - modifier pattern)\n- Phase 68: splat operators (KC 155e919c - parameter extension)\n- Phase 38: lib keyword (C bindings context)\n\n### Tags\nphase-97, union, C-bindings, FFI, boolean-flag-pattern, code-reuse, struct-pattern, parser-only, crystal-compiler, cassandra-validated, exact-copy','\n',char(10)),replace('## Pattern: Boolean Flag Parameter for Syntactically Identical Constructs\n\n### Problem\nImplement union keyword for C binding union types (FFI). CASSANDRA assessment: 98% VERY HIGH confidence based on exact match to Phase 32 (struct) pattern.\n\n### Solution: Code Reuse via Boolean Flag\n\n**Key Strategy**: Follow Phase 32 (struct) boolean flag pattern exactly.\n\n**Grammar**: `union Name ... end` (ident...','\n',char(10)),NULL,'[]','{}',0.8000000000000000444,'2025-10-28T09:14:39.614915','2025-10-28T09:14:39.614921',NULL,0,NULL);
